       if(G.crouchTog) bad.push('holding Shift with W while crouched left the crouch on');
       if(!G.sprinting) bad.push('holding Shift with W while crouched did not sprint (sprinting '+G.sprinting+', stamina '+Math.round(p.stam)+')');
       delete K['ShiftLeft']; delete K['KeyW'];
       // ARM TWO: crouched, then a roll.
       G.crouchTog=true; p.stam=100; p.roll=0; p.rollCd=0; p.downed=false;
       K['KeyW']=true; tryRoll(); delete K['KeyW'];
       if(!(p.roll>0)) bad.push('control: the roll did not start (roll '+p.roll+')');
       if(G.crouchTog) bad.push('rolling left the crouch on');
       // CONTROL: walking without Shift keeps the crouch.
       G.crouchTog=true; p.roll=0; p.rollCd=0; K['KeyW']=true;
       for(var f2=0;f2<4;f2++) __loop(t0+200+f2*16.7);
       delete K['KeyW'];
       if(!G.crouchTog) bad.push('control: walking without Shift cleared the crouch on its own');
       G.crouchTog=false;
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{ try{ var K2=__keys(); for(var q2 in K2) delete K2[q2]; }catch(_k){} try{ G.crouchTog=false; }catch(_g){} __topClear(); __cleanProfile(); }
     return bad.length?bad.join('; '):null; }},
  {v:'11.52',what:'credits and XP are shown at all times in the upper right corner, in the Undercroft and in a raid, above the screens and clear of the CONDITIONS box, and the readout follows the profile when a figure changes',
   run:function(){
     if(!(window.__deploy&&window.__state&&window.__frame&&window.__P&&window.__hubEnter)) return 'SKIP: this fixture cannot deploy and read the screen';
     var el=document.getElementById('topright');
     if(!el) return 'there is no credits and XP readout in the upper right corner';
     var bad=[], prof, keepC, keepX;
     function rect(){ var r=el.getBoundingClientRect(); return {l:r.left,t:r.top,r:r.right,b:r.bottom,w:r.width,h:r.height}; }
     function shown(where){
       var cs=getComputedStyle(el), r=rect();
       if(cs.display==='none'||cs.visibility==='hidden'||parseFloat(cs.opacity)===0) bad.push(where+': the readout is hidden');
       if(!(r.w>40&&r.h>10)) bad.push(where+': the readout has no size ('+Math.round(r.w)+'x'+Math.round(r.h)+')');
       if(!(r.r<=innerWidth+1&&r.r>=innerWidth-48)) bad.push(where+': the readout is not at the right edge (right '+Math.round(r.r)+' of '+innerWidth+')');
       if(!(r.t>=0&&r.t<=40)) bad.push(where+': the readout is not at the top (top '+Math.round(r.t)+')');
       var t=(el.textContent||'').replace(/\s+/g,' ');
       var c=(prof.credits||0).toLocaleString(), x=(prof.xp||0).toLocaleString();
       if(t.indexOf(c)<0) bad.push(where+': the readout does not show the credits '+c+' ("'+t+'")');
       if(t.indexOf(x)<0) bad.push(where+': the readout does not show the XP '+x+' ("'+t+'")');
       if(!/CREDITS/i.test(t)||!/\bXP\b/.test(t)) bad.push(where+': the readout does not say which figure is which ("'+t+'")');
     }
     try{
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       prof=__P(); keepC=prof.credits; keepX=prof.xp;
       // DISTINCTIVE figures no fresh profile carries.
       prof.credits=4471337; prof.xp=98761; saveProfile();
       try{ __hubEnter(); }catch(_h){}
       shown('in the Undercroft');
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       __frame(); __frame();
       prof=__P(); prof.credits=4471337; prof.xp=98761; saveProfile();
       shown('in a raid');
       // CLEAR OF THE CONDITIONS BOX, in screen space. v12.19: HUDBOX.cond is
       // already in screen pixels (drawHUD runs it through hudZoomRect), so it is
       // read as it is; multiplying by the zoom again made this too permissive.
       var HB=(typeof HUDBOX!=='undefined')?HUDBOX.cond:null, r=rect();
       if(!HB) bad.push('control: the CONDITIONS box was not drawn, so the clearance cannot be measured');
       else {
         var condTop=HB.y;
         if(r.b>condTop+1) bad.push('in a raid the readout reaches down to '+Math.round(r.b)+' while the CONDITIONS box starts at '+Math.round(condTop)+', so the two overlap');
       }
       // IT FOLLOWS A CHANGE.
       prof.credits=1234567; saveProfile();
       var t2=(el.textContent||'').replace(/\s+/g,' ');
       if(t2.indexOf((1234567).toLocaleString())<0) bad.push('after the credits changed the readout still says "'+t2+'"');
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
       try{ var pf=__P(); pf.credits=keepC; pf.xp=keepX; saveProfile(); }catch(_r){}
       __topClear(); __cleanProfile();
     }
     return bad.length?bad.join('; '):null; }},
  {v:'11.69',what:'dropping a tactical belt item on the stash says it went to the stash, and it did: it left the backpack and its belt key',
   run:function(){
     if(!(window.__P&&window.__hubEnter&&window.__station)) return 'SKIP: this fixture cannot walk the Undercroft';
     if(typeof say2!=='function') return 'SKIP: no say2 in this build';
     var zone=document.getElementById('stashgrid');
     if(!zone) return 'SKIP: no stash grid in this document';
     var bad=[], prof, got=[], _s2=say2, stale=['back in the ','backpack'].join('');
     try{
       __topClear(); __cleanProfile(); prof=__P();
       try{ __hubEnter(); __station('stash'); }catch(_h){}
       try{ renderHub(); }catch(_r){}
       if(typeof zone.__grabDrop!=='function') return 'SKIP: the stash grid is not a drop zone here (no __grabDrop), so the drop cannot be driven';
       // A medkit in the backpack, on belt key 1.
       prof.kit=['medkit']; prof.hotAssign={0:'medkit'}; prof.stash=[];
       say2=function(t){ got.push(String(t)); };
       zone.__grabDrop('medkit','plan:0');
       say2=_s2;
       var line=got.join(' | ');
       // CONTROL: the item really left the backpack and its key, or the words are not about this drop.
       if((prof.kit||[]).indexOf('medkit')>=0) bad.push('control: the medkit is still in the backpack after the drop');
       if(prof.hotAssign&&prof.hotAssign[0]!==undefined) bad.push('control: the belt key still holds the medkit after the drop');
       if(!got.length) bad.push('control: the drop said nothing at all');
       // THE FIX: the line names where it went.
       if(line.indexOf(stale)>=0) bad.push('the drop said "'+line+'" while taking the item out of the backpack');
       if(line.indexOf('stash')<0) bad.push('the drop does not say the item went to the stash: "'+line+'"');
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{ say2=_s2; __topClear(); __cleanProfile(); }
     return bad.length?bad.join('; '):null; }},
  {v:'13.96',what:'an enemy charge does not turn your hire on you: an enemy pillager charge bursting 40 units from your hire leaves him out of chase, while an ordinary pillager beside the same blast gives chase (machine and pillager AI audit 2026-09-14, finding 1)',
   run:function(){
     if(!(window.__deploy&&window.__state&&window.__endRaid)) return 'SKIP: this fixture cannot deploy';
     if(typeof explodeFrag!=='function'||typeof mkRaider!=='function') return 'SKIP: no charges or pillagers in this build';
     var bad=[];
     try{
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       var g=__state(), p=g.player;
       if(!g||!p) return 'SKIP: no live raid';
       var Z=null, zi;
       for(zi=0;zi<g.zones.length&&!Z;zi++) if(losClear(g.zones[zi].x,g.zones[zi].y,g.zones[zi].x-40,g.zones[zi].y,g.map.segs)&&losClear(g.zones[zi].x,g.zones[zi].y,g.zones[zi].x-40,g.zones[zi].y+40,g.map.segs)) Z=g.zones[zi];
       if(!Z) return 'SKIP: no clear spot beside a ring';
       var M=mkRaider(Z.x,Z.y,null,false); M.merc=1; M.hostile=false; M.grudge=false; M.friendly=1; M.hp=1000; M.maxhp=1000; M.state='follow';
       var R=mkRaider(Z.x,Z.y+40,null,false); R.hostile=true; R.hp=1000; R.maxhp=1000; R.state='loot';
       var H=mkRaider(Z.x+1500,Z.y+1500,null,false); H.hostile=true;
       g.ents.length=0; g.ents.push(M); g.ents.push(R); g.ents.push(H);
       p.x=Z.x+900; p.y=Z.y-900; p.iv=99;
       explodeFrag({x:Z.x-40,y:Z.y+20,t:0,fuse:0,by:H,r:0});
       // CONTROL: an ordinary pillager in the blast gives chase.
       if(R.state!=='chase') return 'SKIP: the enemy charge did not set an ordinary pillager in its blast to chase, so nothing here can be measured';
       // THE FINDING: your hire in the same blast.
       if(M.state==='chase') bad.push('an enemy charge 40 units from your hire set him chasing, which the pillager chase branch turns on you');
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
       try{ var g2=__state(); if(g2){ if(g2.player) g2.player.iv=0; if(!g2.over) __endRaid('abandon'); } }catch(_e){}
       __topClear(); __resetCfg(); __cleanProfile();
     }
     return bad.length?bad.join('; '):null; }},
  {v:'13.95',what:'a Stray clearing your notoriety clears its fade count: helped at notoriety 1 with three extractions counted, both go to zero, while at notoriety 2 the count keeps running (contracts, notoriety and waves audit 2026-09-14, finding 6)',
   run:function(){
     if(!(window.__deploy&&window.__state&&window.__endRaid&&window.__P)) return 'SKIP: this fixture cannot deploy';
     if(typeof mkStray!=='function'||typeof strayGive!=='function') return 'SKIP: no Stray in this build';
     var bad=[], P2=__P(), keep={no:P2.notoriety,ne:P2.notExt,cr:P2.credits};
     function help(noto){
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       var g=__state(); if(!g||!g.player) return null;
       var p=g.player;
       g.ents.length=0; g.hotAssign={}; p.downed=false; p.iv=99;
       var e=mkStray(p.x+20,p.y); e.found=1; g.ents.push(e);
       if(e.want==='ammobox'){ g.bag=[]; p.reserve=400; } else g.bag=[e.want];
       P2.notoriety=noto; P2.notExt=3;
       strayGive(e);
       return {helped:!!e.helped, noto:P2.notoriety, ext:P2.notExt};
