  {v:'13.34',what:'the what-is-new card tells a player coming back that the welcome pack now goes to the stash and how to take a gun from it, Equip as your gun, within the entries the card draws, and its stamp is not older than the stash ruling',
   run:function(){
     if(typeof WHATSNEW==='undefined'||typeof WHATSNEW_VER==='undefined') return 'SKIP: this build has no what-is-new card';
     var bad=[];
     var ver=parseFloat(WHATSNEW_VER);
     if(!(ver>=13.29))
       bad.push('the card still says NEW IN v'+WHATSNEW_VER+', older than his ruling that sends the welcome pack to the stash, so a friend coming back is shown nothing about it');
     var lead=['THE','WELCOME','PACK','GOES','TO','YOUR','STASH'].join(' ');
     var needle=['Equip','as','your','gun'].join(' ');
     var idx=-1;
     for(var i=0;i<WHATSNEW.length;i++){ if(String(WHATSNEW[i]).indexOf(lead)===0){ idx=i; break; } }
     if(idx<0)
       bad.push('no entry on the card says the welcome pack now goes to the stash, so a player who took it before expects its guns in his hands');
     else {
       if(idx>12) bad.push('the stash entry is entry '+(idx+1)+', below the thirteen the card draws, so it is on the list and never on the screen');
       if(String(WHATSNEW[idx]).indexOf(needle)<0) bad.push('the stash entry does not say how to take a gun from the stash');
     }
     return bad.length?bad.join('; '):null; }},
  {v:'13.33',what:'a line that must not be lost waits its turn: with a message showing, two more queued behind it are each shown when the one before runs out, in order and none written over, which is how the rival warning and the loaner line reach the player',
   run:function(){
     if(!(window.__state&&window.__endRaid&&window.__loop&&window.__showScreen)) return 'SKIP: this fixture cannot start a raid or step the loop';
     if(!__vpAlive()) return 'SKIP: the pane has no layout ('+window.innerWidth+'x'+window.innerHeight+'), so the frame loop cannot draw';
     if(typeof startRaid!=='function'||typeof say!=='function') return 'SKIP: this build has no raid to start or no message line';
     var bad=[];
     function endAny(){ try{ var g0=__state(); if(g0&&!g0.over){ g0.player.downed=false; __endRaid('abandon'); } }catch(_0){} }
     try{
       __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile(); endAny();
       startRaid();
       var G2=__state(); if(!G2||G2.over||G2.sim) return 'SKIP: staging: no live raid started';
       var t0=performance.now(), f=0, i;
       // Let landing say what it says, so the queue starts empty.
       for(i=0;i<420;i++){ __loop(t0+(++f)*16.7); }
       // r1334b: nothing else may speak while the queue is measured. A live crier on
       // one seed kept the line busy past the stepping window.
       G2.ents.length=0;
       // r1334c: and no wave either. With nobody alive the spawner sends a man every
       // eight seconds with a line of its own; its clock is held back for the check.
       G2.waveT=-1e9;
       G2.msgQ=[]; G2.msgT=0;
       var L1=['first','line','of','three'].join(' '), L2=['second','line','of','three'].join(' '), L3=['third','line','of','three'].join(' ');
       say(L1);
       if(typeof sayWhenFree==='function'){ sayWhenFree(L2); sayWhenFree(L3); }
       else { say(L2); say(L3); }   // v13.32 and earlier: the direct say the rival warning used
       var seen=[];
       function note(){ var g=__state(); if(g&&g.msg&&(seen.length===0||seen[seen.length-1]!==g.msg)) seen.push(String(g.msg)); }
       note();
       for(i=0;i<720;i++){ __loop(t0+(++f)*16.7); note(); }
       var order=[L1,L2,L3].map(function(l){ return seen.indexOf(l); });
       if(order[0]<0) bad.push('the line shown first was never on screen');
       if(order[1]<0) bad.push('a second line said while the first was showing was written over and never shown [shown: '+seen.join(' | ').slice(0,200)+']');
       if(order[2]<0) bad.push('a third line queued behind the second was lost [shown: '+seen.join(' | ').slice(0,200)+']');
       if(order[0]>=0&&order[1]>=0&&order[2]>=0&&!(order[0]<order[1]&&order[1]<order[2]))
         bad.push('the queued lines were shown out of order ['+seen.join(' | ').slice(0,200)+']');
       // CONTROL: with nothing showing, sayWhenFree says at once rather than waiting.
       if(typeof sayWhenFree==='function'){
         G2.msgQ=[]; G2.msgT=0;
         var L4=['said','at','once'].join(' ');
         sayWhenFree(L4);
         if(__state().msg!==L4) bad.push('control: with nothing showing, a line through the queue was held back instead of said at once');
       }
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
       endAny();
       try{ __topClear(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'13.32',what:'the quick ascent, which skips the sector page, tells a player who lands with a loaner that his own gun waits in his stash and how to take it, after the weather line rather than over it, and only when his stash holds a gun and nothing of his own is equipped',
   run:function(){
     if(!(window.__hubEnter&&window.__hb&&window.__keys&&window.__showScreen&&window.__state&&window.__endRaid&&window.__P&&window.__loop)) return 'SKIP: this fixture cannot walk the floor or step the loop';
     if(typeof updateHubWorld!=='function'||typeof startRaid!=='function') return 'SKIP: this build has no floor update or no raid to start';
     if(!ITEMS.gun_smg||!WEAPONS.smg||!WEAPONS.pistol) return 'SKIP: this build has no stash gun item to stage';
     // r1334: the frame loop draws, and a pane with no layout throws in drawImage.
     if(!__vpAlive()) return 'SKIP: the pane has no layout ('+window.innerWidth+'x'+window.innerHeight+'), so the frame loop cannot draw';
     var bad=[], P2=__P();
     var keep={equipped:P2.equipped,equippedSec:P2.equippedSec,weapons:(P2.weapons||[]).slice(),stash:(P2.stash||[]).slice(),kit:(P2.kit||[]).slice(),freeKit:P2.freeKit,hot:JSON.parse(JSON.stringify(P2.hotAssign||{}))};
     var needle=['Equip','as','your','gun'].join(' ');
     function endAny(){ try{ var g0=__state(); if(g0&&!g0.over){ g0.player.downed=false; __endRaid('abandon'); } }catch(_0){} }
     function ascend(equipped,weapons,stash){
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       endAny();
       __showScreen('hub'); __hubEnter();
       var HBx=__hb(); if(!HBx||!HBx.stations) return {none:'no floor to stand on'};
       var lift=null, i;
       for(i=0;i<HBx.stations.length;i++) if(HBx.stations[i].id==='lift') lift=HBx.stations[i];
       if(!lift) return {none:'this build has no lift'};
       P2.freeKit=0; P2.kit=[]; P2.hotAssign={}; P2.equipped=equipped; P2.equippedSec='none'; P2.weapons=weapons.slice(); P2.stash=stash.slice();
       var K=__keys(), k;
       for(k in K) delete K[k];
       HBx.player.x=lift.x; HBx.player.y=lift.y; HBx.eLock=false;
       K.KeyR=1;
       for(i=0;i<6;i++) updateHubWorld(0.05);
       for(k in K) delete K[k];
       var G2=__state();
       if(!G2||G2.over||G2.sim) return {none:'the quick ascent key did not start a raid'};
       var seen=[], t0=performance.now();
       function note(){ var g=__state(); if(g&&g.msg&&seen.indexOf(g.msg)<0) seen.push(String(g.msg)); }
       note();
       for(i=0;i<300;i++){ __loop(t0+(i+1)*16.7); note(); }
       return {issued:!!G2.player.wepIssued, seen:seen};
     }
     try{
       // ONE: nothing equipped, a pack gun in the stash. He lands with a loaner.
       var A=ascend('fists',['pistol'],['gun_smg','bandage']);
       if(A.none) return 'SKIP: '+A.none;
       if(!A.issued) return 'SKIP: staging: the quick ascent did not issue a loaner, so there is nothing to measure';
       var hitA=A.seen.filter(function(m){ return m.indexOf(needle)>=0; });
       if(!hitA.length)
         bad.push('a player who takes the quick ascent with nothing equipped lands with a loaner and is never told his own gun waits in the stash [shown: '+A.seen.join(' | ').slice(0,200)+']');

       // TWO: nothing equipped, and no gun in the stash either.
       var B=ascend('fists',['pistol'],['bandage']);
       if(!B.none&&B.seen.some(function(m){ return m.indexOf(needle)>=0; }))
         bad.push('a player with no gun in his stash is told on landing to equip one from it');

       // THREE: a gun of his own equipped, another in the stash. No loaner, no line.
       var C=ascend('pistol',['pistol'],['gun_smg']);
       if(!C.none&&C.issued) bad.push('staging: a player with his own pistol equipped was issued a loaner');
       else if(!C.none&&C.seen.some(function(m){ return m.indexOf(needle)>=0; }))
         bad.push('a player who went up with his own gun is told he is carrying a loaner');
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
       endAny();
       try{ P2.equipped=keep.equipped; P2.equippedSec=keep.equippedSec; P2.weapons=keep.weapons; P2.stash=keep.stash; P2.kit=keep.kit; P2.freeKit=keep.freeKit; P2.hotAssign=keep.hot; saveProfile(); }catch(_r){}
       try{ var K2=__keys(); for(var k2 in K2) delete K2[k2]; }catch(_k){}
       try{ __topClear(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'13.31',what:'the sector page the lift opens tells a player with nothing equipped that he has a gun of his own in his stash and how to take it, Equip as your gun, and only when his stash holds a gun (the pack guns wait there since his ruling)',
   run:function(){
     if(typeof renderSector!=='function') return 'SKIP: this fixture cannot draw the sector page';
     var K=document.getElementById('sectorkit'); if(!K) return 'SKIP: this build has no sector kit box';
     if(!ITEMS.gun_smg||!WEAPONS.smg) return 'SKIP: this build has no stash gun item to stage';
     var bad=[];
     var keep={equipped:P.equipped,equippedSec:P.equippedSec,weapons:(P.weapons||[]).slice(),stash:(P.stash||[]).slice(),kit:(P.kit||[]).slice(),freeKit:P.freeKit};
     var needle=['Equip','as','your','gun'].join(' ');
     function boxText(){ try{ renderSector(); }catch(_s){} return String(K.textContent||''); }
     try{
       // ONE: nothing equipped, and a pack gun waiting in the stash.
       P.freeKit=0; P.equipped='fists'; P.equippedSec='none'; P.weapons=['pistol']; P.kit=[]; P.stash=['gun_smg','bandage'];
       var a=boxText();
       if(!a) return 'SKIP: the sector page drew an empty kit box';
       if(a.indexOf(needle)<0)
         bad.push('a player with nothing equipped and a gun of his own in his stash is told only that he goes up with an issued gun, on the last screen before the lift ['+a.slice(0,140)+']');

       // TWO: nothing equipped and no gun in the stash either.
       P.stash=['bandage'];
       var b=boxText();
       if(b.indexOf(needle)>=0)
         bad.push('a player with no gun in his stash is told to equip one from it, so he goes looking for a gun that is not there');

       // THREE: a gun equipped, with another in the stash. He is not going up with a loaner.
       P.equipped='pistol'; P.stash=['gun_smg'];
       var c=boxText();
       if(c.indexOf(needle)>=0)
         bad.push('a player who already has a gun equipped is told to equip one from his stash');
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
       try{ P.equipped=keep.equipped; P.equippedSec=keep.equippedSec; P.weapons=keep.weapons; P.stash=keep.stash; P.kit=keep.kit; P.freeKit=keep.freeKit; saveProfile(); }catch(_r){}
       try{ renderSector(); }catch(_rs){}
       try{ __topClear(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'13.29',what:'the welcome pack goes to the stash: both guns land there as gun items, nothing is added to the armoury, nothing is equipped for him, and every row in the window says to your stash (his ruling of 2026-09-13)',
   run:function(){
     if(typeof maybeWelcome!=='function'||typeof WELCOME_PACK==='undefined') return 'SKIP: this fixture cannot open the welcome pack';
     var md=document.getElementById('welcomemodal'), box=document.getElementById('welcomelist');
     if(!md||!box) return 'SKIP: this build has no welcome pack window';
     var bad=[];
     var keep={runs:P.runs,welcomed:P.welcomed,stash:(P.stash||[]).slice(),weapons:(P.weapons||[]).slice(),equipped:P.equipped,equippedSec:P.equippedSec};
     try{
       var guns=WELCOME_PACK.guns||[];
       if(guns.length<2) return 'SKIP: the pack carries fewer than two guns';
       P.runs=0; P.welcomed=0; P.stash=[]; P.weapons=['pistol']; P.equipped='fists'; P.equippedSec='none';
       maybeWelcome();
       if(!md.classList.contains('on')) return 'SKIP: the welcome pack did not open for a brand-new player';
       box.querySelectorAll('.row').forEach(function(r){
         var t=String(r.textContent||'').replace(/\s+/g,' ');
         if(t.indexOf('to your stash')<0) bad.push('a row in the pack window does not say it goes to the stash: ['+t+']');
       });
       var take=document.getElementById('welcometake');
       if(!take) return 'SKIP: this build has no TAKE button';
       take.click();
       for(var i=0;i<guns.length;i++){
         var gi='gun_'+guns[i];
         if((P.stash||[]).indexOf(gi)<0)
           bad.push('taking the pack did not put the '+guns[i]+' in the stash as an item, so the pack did not go to the stash');
         if((P.weapons||[]).indexOf(guns[i])>=0)
           bad.push('taking the pack added the '+guns[i]+' to the armoury, which his ruling moved to the stash');
       }
       if(P.equipped!=='fists')
         bad.push('taking the pack equipped '+String(P.equipped)+' for him, when his ruling is that the pack goes to the stash and he packs on purpose');
       if(P.equippedSec!=='none')
         bad.push('taking the pack filled his second slot with '+String(P.equippedSec)+' for him');
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
       try{ md.classList.remove('on'); }catch(_m){}
       try{ P.runs=keep.runs; P.welcomed=keep.welcomed; P.stash=keep.stash; P.weapons=keep.weapons; P.equipped=keep.equipped; P.equippedSec=keep.equippedSec; saveProfile(); }catch(_r){}
       try{ __topClear(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'13.28',what:'the save you are on is tagged NEW until it has a raid and CONTINUING after, instead of telling a player on his first ever launch that he is continuing something',
   run:function(){
     if(typeof titleRefresh!=='function'||typeof saveProfile!=='function') return 'SKIP: this fixture cannot save and redraw the save list';
     var host=document.getElementById('slotlist'); if(!host) return 'SKIP: this build draws no save list';
     if(typeof SLOT==='undefined') return 'SKIP: this fixture cannot tell which save is current';
     var bad=[], keepRuns=P.runs;
     function tag(){
       try{ titleRefresh(); }catch(_t){}
       var row=host.querySelector('[data-slot="'+SLOT+'"]');
       if(!row) return null;
       var sp=row.querySelector('b span');
       return sp?String(sp.textContent||'').trim():'';
     }
     try{
       // ONE: the current save has never been raided.
       P.runs=0; saveProfile();
       var a=tag();
       if(a===null) return 'SKIP: the save list drew no row for the current save';
       if(a==='CONTINUING')
         bad.push('a save with no raids on it is tagged CONTINUING, right beside the line that says 0 raids, so a player on his first ever launch is told he is continuing something');
       else if(a!=='NEW')
         bad.push('a save with no raids is tagged ['+a+'] rather than NEW');

       // TWO: the current save has a raid.
       P.runs=1; saveProfile();
       var b=tag();
       if(b!=='CONTINUING')
         bad.push('a save that has been played is tagged ['+String(b)+'] rather than CONTINUING, so the fix took the tag away from the case it was right for');
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
       try{ P.runs=keepRuns; saveProfile(); titleRefresh(); }catch(_r){}
       try{ __topClear(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'13.27',what:'the title screen stops promising a new player a walkthrough that does not exist: it tells him to take the welcome pack only when the pack will be offered, and to walk to ENTER RAID either way',
   run:function(){
     if(typeof titleRefresh!=='function') return 'SKIP: this fixture cannot redraw the title line';
     var sub=document.getElementById('titlesub'); if(!sub) return 'SKIP: this build draws no line under the title';
     var bad=[];
     var keep={runs:P.runs,welcomed:P.welcomed,stash:(P.stash||[]).slice(),weapons:(P.weapons||[]).slice()};
     function line(){ try{ titleRefresh(); }catch(_t){} return String(sub.textContent||''); }
     try{
       // ONE: a brand-new player the game will offer the pack to.
       P.runs=0; P.welcomed=0; P.stash=[]; P.weapons=['pistol'];
       var a=line();
       if(!a) return 'SKIP: the title line drew nothing for a player with no raids';
       if(/walk you through/i.test(a))
         bad.push('a brand-new player is promised that the Undercroft will walk him through it, and nothing in the game does: the first sentence he reads is a promise no screen keeps');
       if(a.indexOf('welcome pack')<0)
         bad.push('a new player who is about to be offered the welcome pack is not told to take it: ['+a+']');
       if(a.indexOf('ENTER RAID')<0)
         bad.push('a new player is not told where to go to start: ['+a+']');

       // TWO: a player with no raids who has already been welcomed.
       P.runs=0; P.welcomed=1; P.stash=[]; P.weapons=['pistol'];
       var b=line();
       if(b.indexOf('welcome pack')>=0)
         bad.push('a player who will never be offered the welcome pack is told to take it, so he goes looking for a pack that does not appear: ['+b+']');
       if(b.indexOf('ENTER RAID')<0)
         bad.push('a player with no raids who has already been welcomed is not told where to go: ['+b+']');
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
       try{ P.runs=keep.runs; P.welcomed=keep.welcomed; P.stash=keep.stash; P.weapons=keep.weapons; titleRefresh(); }catch(_r){}
       try{ __topClear(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'13.26',what:'the map screen shows every player the sector line he rewrote: the test robot extract rate in that map, without first contact, containers or median haul, whether or not that player has raided there (his baked edits matched only his own run counts)',
   run:function(){
     if(typeof renderSector!=='function'||typeof FIXED_MAPS==='undefined'||typeof SECTOR_MEAS==='undefined') return 'SKIP: this fixture cannot draw the map screen';
     var host=document.getElementById('sectorlist'); if(!host) return 'SKIP: there is no map list to draw into';
     var bad=[], keepLog=(P.log||[]).slice();
     function title(n){ return String(n||'').toLowerCase().replace(/\b[a-z]/g,function(c){ return c.toUpperCase(); }); }
     function rows(){ renderSector(); var out=[]; host.querySelectorAll('.sectorpick').forEach(function(r){ out.push(String(r.textContent||'').replace(/\s+/g,' ')); }); return out; }
     function judge(label){
       var rs=rows();
       if(rs.length<2){ bad.push(label+': the map screen drew '+rs.length+' maps, not both'); return; }
       for(var i=0;i<rs.length&&i<FIXED_MAPS.length;i++){
         var t=rs[i], nm=FIXED_MAPS[i].name, MS=SECTOR_MEAS[i]||{};
         if(MS.ext===undefined) continue;
         if(t.indexOf('first contact ~')>=0||t.indexOf('median haul')>=0||t.indexOf('containers a raid')>=0)
           bad.push(label+': '+nm+' still shows first contact, containers or median haul, the three figures he cut from this line');
         if(t.indexOf('of its raids in '+title(nm)+'.')<0)
           bad.push(label+': '+nm+' does not give the extract rate for that map in his words, ending "of its raids in '+title(nm)+'."');
       }
     }
     try{
       P.log=[];
       judge('a player who has never raided either map');
       P.log=[]; for(var j=0;j<FIXED_MAPS.length;j++) P.log.push({mapName:FIXED_MAPS[j].name});
       judge('a player with one run on each map');
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
       try{ P.log=keepLog; renderSector(); }catch(_r){}
       try{ __topClear(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'13.25',what:'the what-is-new card no longer promises Escape keeps fullscreen where it cannot: an entry about Escape and fullscreen says it only holds in the game own tab, and what happens inside another page such as itch (his report of 2026-09-12)',
   run:function(){
     if(typeof WHATSNEW==='undefined') return 'SKIP: this build has no what-is-new card';
     var bad=[], about=0, honest=0;
     for(var i=0;i<WHATSNEW.length;i++){
       var t=String(WHATSNEW[i]), u=t.toUpperCase();
       if(u.indexOf('ESC')<0||u.indexOf('FULLSCREEN')<0) continue;
       about++;
       var qualified=(u.indexOf('OWN TAB')>=0)||(u.indexOf('ANOTHER PAGE')>=0);
       if(u.indexOf('NO LONGER DROPS YOU OUT OF FULLSCREEN')>=0&&!qualified)
         bad.push('the card still promises that Escape no longer drops you out of fullscreen, and on itch, where every friend plays, it does, so the one line about it is false in exactly the place it is read');
       if(qualified) honest++;
     }
     if(about&&!honest)
       bad.push('no entry about Escape and fullscreen says what happens when the game is played inside another page, so a player on itch is told nothing true about the key he reported');
     return bad.length?bad.join('; '):null; }},
  {v:'13.24',what:'finding a better gun with the second slot free tells you to swap to it on the tactical belt, not to press X, which searches',
   run:function(){
     if(!(window.__deploy&&window.__state&&window.__loop&&window.__keysRef&&window.__endRaid))
       return 'SKIP: this fixture cannot drive a live raid';
     if(typeof ITEMS==='undefined'||typeof WEAPONS==='undefined'||typeof WTIER==='undefined')
       return 'SKIP: this fixture cannot reach the gun tables';
     var bad=[], _say=say, heard=[];
     var T0=performance.now();
     function frames(k){ for(var f=0;f<(k||6);f++){ T0+=16.7; var st=__state(); if(!st||st.over) return; __loop(T0); } }
     function keysOff(){ var K=__keysRef(); for(var kk in K) K[kk]=false; }
     try{
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       var g=__state();
       if(!g||!g.containers||!g.containers.length) return 'SKIP: this landing has no containers';
       var p=g.player;
       // THE BEST GUN IN THE TABLE, so the tier rise is guaranteed.
       var best=null, bt=-1, k;
       for(k in ITEMS){
         var it=ITEMS[k];
         if(it&&it.use==='gun'&&it.gk&&WEAPONS[it.gk]){ var t=WTIER[it.gk]||0; if(t>bt){ bt=t; best=k; } }
       }
       if(!best||!(bt>(WTIER[p.wep.id]||0))) return 'SKIP: nothing in the gun table outranks the gun in hand';
       var box=null;
       for(var i=0;i<g.containers.length;i++) if(!g.containers[i].opened){ box=g.containers[i]; break; }
       if(!box) return 'SKIP: this landing has no unopened container';
       box.loot=[best]; box.opened=false;
       p.sec=null;   // the second slot is free: the branch under test
       p.x=box.x; p.y=box.y; p.downed=false;
       keysOff(); frames(3);
       say=function(m){ heard.push(String(m)); try{ return _say.apply(null,arguments); }catch(_s){} };
       keysOff(); __keysRef()['KeyX']=true;
       for(var w=0;w<60;w++){ frames(10); if(box.opened) break; }
       keysOff(); frames(4);
       if(!box.opened) return 'SKIP: the container never opened, so nothing was picked up';
       var line='';
