       pollPad();
       for(a=0;a<ACTS.length;a++){
         var fb=ACTS[a].replace('Key','');
         if(keyLabel(ACTS[a],fb)!==fb){
           bad.push('control: with no pad connected the station prompt still names a controller button rather than the ['+fb+'] key');
