  {v:'12.44',what:'the extraction window never outlives the raid clock: an extraction arriving with two seconds left announces what the raid actually has and not the three second floor, on the number and on the ring badge alike, while a full clock and a raid with the clock switched off both still give the ordinary thirty seconds (2026-09-07 audit)',
   run:function(){
     if(!(window.__deploy&&window.__state&&window.__endRaid&&window.__topClear&&window.__runPrep&&window.__resetCfg&&window.__pinDefaults&&window.__cleanProfile)) return 'SKIP: this fixture cannot deploy a raid';
     if(typeof tickExtractPoints!=='function'||typeof zoneBadge!=='function') return 'SKIP: this build has no extraction ticker or ring badge to read';
     var bad=[];
     // Land a ship on a ring with a chosen amount of raid clock left, by running
     // the real ticker one step past the end of the beacon. Returns the window
     // it created and the words the ring badge prints for it.
     function land(left,clockOn){
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],mapIx:0,seed:4242});
       var g=__state(); if(!g||!g.player||!g.zones||!g.zones.length) return null;
       var z=g.active||g.zones[0], p=g.player;
       CFG.raidSec=clockOn?540:0;
       g.active=z; z.open=true; z.hold=null; z.holdMax=null; z.boardT=0; z.pullT=null;
       z.beaconT=0.001; g.beaconT=z.beaconT;
       g.timeLeft=left;
       p.downed=false; p.iv=99; p.x=z.x; p.y=z.y;
       tickExtractPoints(0.01);
       if(z.hold===null||z.hold===undefined) return {none:1};
       return {hold:z.hold,left:g.timeLeft,badge:String(zoneBadge(z)||'')};
     }
     function badgeSeconds(txt){
       var m=/([0-9]+)S UNTIL EXTRACTION ENDS/.exec(txt);
       return m?(+m[1]):null;
     }
     try{
       // THE FINDING: the ship lands with two seconds of raid left.
       var A=land(2.0,true);
       if(!A) return 'SKIP: no raid with an extraction point to land an extraction on';
       if(A.none) return 'SKIP: one step past the end of the countdown opened no extraction window, so there is nothing to read here';
       if(A.hold>A.left+0.001)
         bad.push('the extraction window says '+A.hold+' seconds with only '+A.left+' left on the raid clock, so the timer kills him with the countdown still running');
       var sec=badgeSeconds(A.badge);
       if(sec===null) bad.push('control: the ring badge did not print a seconds figure at all ['+A.badge+'], so what he reads cannot be checked here');
       else if(sec>Math.max(0,Math.ceil(A.left)))
         bad.push('the ring badge reads "'+A.badge+'" with '+A.left+' seconds of raid left, so every readout he has is promising him time the raid does not have');
       if(!(A.hold>0)) bad.push('the extraction window came out at '+A.hold+', which reads as no window at all');
       // CONTROL ONE: a full clock still gives the ordinary thirty seconds.
       var B=land(540,true);
       if(B&&!B.none&&Math.abs(B.hold-30)>0.2) bad.push('control: with a full raid clock the extraction window is '+B.hold+' and not the ordinary 30, so the clamp has changed a normal extraction');
       // CONTROL TWO: with the clock switched off it is still thirty, which is
       // the v12.24 rule and the reason this clamp is guarded at all.
       var C=land(0,false);
       if(C&&!C.none&&Math.abs(C.hold-30)>0.2) bad.push('control: with the raid clock switched off the extraction window is '+C.hold+' and not 30, so the v12.24 rule has been undone');
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
       try{ var gz=__state(); if(gz&&!gz.over){ gz.player.downed=false; __endRaid('abandon'); } }catch(_e){}
       __topClear(); __resetCfg(); __cleanProfile();
     }
     return bad.length?bad.join('; '):null; }},
  {v:'12.43',what:'a profile this build creates is born already migrated: the save a brand new player writes after one session on the second sector comes back from his own second load with the seal record and the explored map still on it, while a save that genuinely predates the one-map fold is still folded exactly as it was (2026-09-08 first-hour audit)',
   run:function(){
     if(!(window.__P&&window.__applyLoaded)) return 'SKIP: this fixture cannot drive the loader synchronously';
     var bad=[], keep=null;
     try{
       __topClear(); __runPrep();
       keep=JSON.parse(JSON.stringify(__P()));
       // The literal a new profile is born from lives at file scope and nothing
       // returns it, so it is read out of the page and evaluated. The needle is
       // built here rather than written, or it would match this check.
       var SRC='', sc=document.getElementsByTagName('script'), i;
       for(i=0;i<sc.length;i++) SRC+=(sc[i].textContent||'');
       var NEED='var '+'P='+'{'+'cre'+'dits:';
       var a=SRC.indexOf(NEED);
       if(a<0) return 'SKIP: the born profile is not in this page';
       var lo=a+NEED.indexOf('{');
       var hi=SRC.indexOf('}'+';',lo);
       if(hi<0) return 'SKIP: the born profile has no end in this page';
       var born=null;
       try{ born=(new Function('return '+SRC.slice(lo,hi+1)))(); }catch(_b){ born=null; }
       if(!born||typeof born.credits!=='number') return 'SKIP: the born profile did not read back as a profile';
       // ONE SESSION ON THE SECOND SECTOR. The seal record and the explored
       // bitmap are both stored under the sector index, and the fog is banked at
       // the end of every raid whatever the outcome, so this is what his profile
       // holds when he closes the tab on day one.
       born.seals={}; born.seals['1']={cut:25,tot:40};
       born.mapSeen={}; born.mapSeen['1']='what he walked on the mile';
       if(!(born.seals['1']&&born.mapSeen['1'])) return 'SKIP: the first session could not be staged';
       var hadStamp=!!born.mig739;
       // HIS SECOND LOAD, through the real loader.
       __applyLoaded(born);
       var P2=__P();
       if(!(P2.seals&&P2.seals['1']))
         bad.push('the cutting he did at the great door on the second sector was deleted by his own second load, and the run report had told him it was banked'+(hadStamp?'':': the profile he was born with carries no stamp for the one-map fold, so a repair meant for old saves ran once on his brand new one'));
       if(!(P2.mapSeen&&P2.mapSeen['1']))
         bad.push('the map he explored on the second sector was deleted by his own second load, which happens on any outcome because the fog is banked at the end of every raid');
       // CONTROL: a save that really is older than the fold must still be folded,
       // or a green arm above would only mean the migration had been removed.
       var old=(new Function('return '+SRC.slice(lo,hi+1)))();
       delete old.mig739;
       old.seals={}; old.seals['2']={cut:11,tot:40};
       old.mapSeen={}; old.mapSeen['2']='an old two-map save';
       __applyLoaded(old);
       var P3=__P();
       if(!(P3.seals&&P3.seals['0']&&P3.seals['0'].cut===11))
         bad.push('control: a save from before the one-map fold was not folded, so its cutting did not move down to the sector that survived');
       if(P3.seals&&P3.seals['2'])
         bad.push('control: a save from before the one-map fold kept its third sector record, so the fold did not run at all');
       if(!P3.mig739)
         bad.push('control: a save from before the one-map fold was not stamped afterwards, so it would be folded again on every load');
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
       try{ if(keep) __applyLoaded(keep); saveProfile(); }catch(_p){}
       try{ __topClear(); __resetCfg(); __cleanProfile(); }catch(_c){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'12.42',what:'a gun that goes through the backpack keeps its magazine: loaded plus reserve is conserved across a stow and an equip, on a full gun and on an empty one, so stowing no longer throws the load away and re-equipping no longer conjures half a magazine, while a gun found in the field still arrives on half a magazine (2026-09-07 audit)',
   run:function(){
     if(!(window.__deploy&&window.__state&&window.__topClear&&window.__runPrep&&window.__resetCfg&&window.__pinDefaults&&window.__cleanProfile)) return 'SKIP: this fixture cannot deploy a raid';
     if(typeof bagHeldGun!=='function'||typeof equipFromBag!=='function') return 'SKIP: this build cannot bag and re-equip a gun';
     if(!(WEAPONS&&WEAPONS.lmg&&WEAPONS.lmg.mag===60&&ITEMS&&ITEMS.gun_lmg&&ITEMS.gun_dmr&&WEAPONS.dmr)) return 'SKIP: the Support MG is no longer a sixty round gun, so this staging cannot be built';
     var bad=[];
     // The rounds are conserved across four places, not three: loaded, stowed on
     // the other gun, in the reserve, and riding with a gun in the backpack.
     function total(p){
       var t=(p.ammo|0)+(p.secAmmo|0)+(p.reserve|0), g=__state(), k, q, j;
       if(g&&g.stowAmmo) for(k in g.stowAmmo){ q=g.stowAmmo[k];
         if(q&&q.length) for(j=0;j<q.length;j++) t+=(q[j]|0); }
       return t;
     }
     function arm(loaded){
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],mapIx:0,seed:4242});
       var g=__state(); if(!g||!g.player) return null;
       var p=g.player, w={},k;
       for(k in WEAPONS.lmg) w[k]=WEAPONS.lmg[k];
       p.downed=false; p.roll=0; g.over=false; g.paused=false;
       p.wep=w; p.ammo=loaded; p.wepIssued=false; p.wepFromArmory=false; p.swapped=false;
       p.sec=WEAPONS.fists; p.secAmmo=0; p.secIssued=true; p.secFromArmory=false;
       p.reserve=0; g.bag=[]; g.stowAmmo=null;
       var t0=total(p);
       if(!bagHeldGun('gunA')) return {skip:'the Support MG would not go into the backpack'};
       var ix=g.bag.indexOf('gun_lmg');
       if(ix<0) return {skip:'the Support MG did not arrive in the backpack'};
       var t1=total(p);
       if(!equipFromBag(ix,1)) return {skip:'the Support MG would not come back out of the backpack'};
       return {t0:t0,t1:t1,t2:total(p),ammo:(p.ammo|0),res:(p.reserve|0)};
     }
     try{
       // THE FINDING, full: forty seven loaded, nothing in reserve.
       var A=arm(47);
       if(!A) return 'SKIP: no live raid to stage a gun in';
       if(A.skip) return 'SKIP: '+A.skip;
       if(A.t1!==A.t0) bad.push('putting a gun in the backpack threw its magazine away: the rounds he owns went from '+A.t0+' to '+A.t1+', so '+(A.t0-A.t1)+' of them stopped existing while the gun sat in the backpack');
       if(A.t2!==A.t0) bad.push('a gun through the backpack came back with a different amount of ammunition than it went in with: loaded plus reserve went from '+A.t0+' to '+A.t2);
       if(A.ammo!==47) bad.push('the Support MG came back out of the backpack on '+A.ammo+' rounds, not the 47 it went in with');
       // THE FINDING, the other way: an EMPTY gun, which is the faucet.
       var B=arm(0);
       if(B.skip) return 'SKIP: '+B.skip;
       if(B.t2!==0) bad.push('an empty gun through the backpack came back with '+B.t2+' rounds that no reserve paid for, and the trip can be repeated as often as he likes');
       // CONTROL: HIS RULE FOR A GUN FOUND IN THE FIELD IS UNTOUCHED. A key that
       // was never stowed has no load to remember, so it still arrives on half a
       // magazine; without this a fix that simply handed out nothing reads green.
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],mapIx:0,seed:4242});
       var g2=__state(), p2=g2.player;
       p2.downed=false; p2.roll=0; g2.over=false; g2.paused=false;
       p2.wep=WEAPONS.fists; p2.ammo=0; p2.wepIssued=false; p2.wepFromArmory=false; p2.swapped=false;
       p2.sec=WEAPONS.fists; p2.secAmmo=0; p2.secIssued=true; p2.secFromArmory=false;
       p2.reserve=0; g2.bag=['gun_dmr']; g2.stowAmmo=null;
       var want=Math.ceil(WEAPONS.dmr.mag/2);
       if(!equipFromBag(0,1)) bad.push('control: a gun found in the field would not come out of the backpack at all');
       else if((p2.ammo|0)!==want) bad.push('control: a Marksman Rifle found in the field came up on '+(p2.ammo|0)+' rounds, not the half magazine of '+want+' that is his rule for a find');
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
       try{ var gz=__state(); if(gz){ gz.stowAmmo=null; if(gz.bag) gz.bag.length=0; } }catch(_e){}
       try{ var g3=__state(); if(g3&&!g3.over){ g3.player.downed=false; __endRaid('abandon'); } }catch(_e2){}
       __topClear(); __resetCfg(); __cleanProfile();
     }
     return bad.length?bad.join('; '):null; }},
  {v:'12.41',what:'the key on an empty throwable cell spends nothing from another cell: it names what is missing and puts the gun up instead of quietly walking the hidden selector on and throwing the grenade you did have, on the derived cell, the assigned cell and the cook alike, while a cell that does hold one still throws it (closes the not-verified line on v12.08)',
   run:function(){
     if(!(window.__deploy&&window.__state&&window.__P&&window.__topClear&&window.__runPrep&&window.__resetCfg&&window.__pinDefaults&&window.__cleanProfile)) return 'SKIP: this fixture cannot deploy a raid';
     if(typeof useHot!=='function'||typeof setHot!=='function'||typeof hotbarSlots!=='function'||typeof doThrow!=='function'||typeof startCook!=='function') return 'SKIP: this build has no belt use path';
     if(!(THROWKEYS&&THROWKEYS.length===3&&ITEMS&&ITEMS.frag&&ITEMS.smoke)) return 'SKIP: this build does not carry three throwables';
     var bad=[];
     function cellOf(k){ var sl=hotbarSlots(); for(var i=0;i<sl.length;i++) if(sl[i]&&sl[i].k===k) return i; return -1; }
     try{
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],mapIx:0,seed:4242});
       var g=__state(); if(!g||!g.player) return 'SKIP: no live raid to throw in';
       var p=g.player;
       // TWO SMOKE AND NOTHING ELSE: the cell he presses is empty, and the cell
       // the old code walked to is not, which is the whole of the finding.
       g.pouch={smoke:2,decoy:0,frag:0};
       p.downed=false; p.roll=0; p.cooking=0; p.cookT=0; p.cookKind=null;
       var fragCell=cellOf('throw:frag'), smokeCell=cellOf('throw:smoke');
       if(fragCell<0||smokeCell<0) return 'SKIP: this build has no derived Frag and Smoke cells to press';
       // THE FINDING, the derived cell reached by the key.
       g.hot=-1; setHot(fragCell);
       if(g.tsel!==THROWKEYS.indexOf('frag')) return 'staging: pressing the Frag cell did not point the selector at the Frag';
       var thr0=g.throws.length, sm0=g.pouch.smoke, tsel0=g.tsel;
       g.msg=''; useHot();
       if(g.pouch.smoke!==sm0) bad.push('the key on the empty Frag cell spent a Smoke Canister: the pouch went from '+sm0+' to '+g.pouch.smoke);
       if(g.throws.length!==thr0) bad.push('the key on the empty Frag cell put '+(g.throws.length-thr0)+' throwable(s) in the air from a cell he did not press');
       if(g.tsel!==tsel0) bad.push('the key on the empty Frag cell walked the hidden selector from '+THROWKEYS[tsel0]+' to '+THROWKEYS[g.tsel]+', so the belt and the hand no longer agree');
       if(String(g.msg||'').indexOf(ITEMS.frag.name)<0) bad.push('the key on the empty Frag cell did not name what is missing; it said "'+(g.msg||'')+'"');
       // THE SAME THING BY THE ASSIGNED CELL, which is a second door to doThrow.
       g.pouch={smoke:2,decoy:0,frag:0}; g.hotAssign={}; g.hotAssign[1]='frag';
       g.hot=-1; setHot(1);
       var thr1=g.throws.length, sm1=g.pouch.smoke;
       g.msg=''; useHot();
       if(g.pouch.smoke!==sm1||g.throws.length!==thr1) bad.push('the assigned Frag cell spent a Smoke Canister: the pouch went from '+sm1+' to '+g.pouch.smoke+' and '+(g.throws.length-thr1)+' went in the air');
       g.hotAssign={};
       // AND THE COOK, which took the same branch.
       g.pouch={smoke:2,decoy:0,frag:0}; p.cooking=0; p.cookT=0; p.cookKind=null;
       g.hot=-1; setHot(fragCell);
       var sm2=g.pouch.smoke;
       g.msg=''; var ck=startCook();
       if(ck) bad.push('cooking an empty Frag cell reported that a grenade was in his hand');
       if(g.pouch.smoke!==sm2) bad.push('cooking the empty Frag cell pulled the pin on a Smoke Canister: the pouch went from '+sm2+' to '+g.pouch.smoke);
       if(p.cooking) bad.push('cooking the empty Frag cell left a live grenade in his hand, kind '+p.cookKind);
       p.cooking=0; p.cookT=0; p.cookKind=null;
       // CONTROL: a cell that DOES hold one still throws it, so a fix that simply
       // stopped throwing altogether cannot read green here.
