       else if(g.throws[g.throws.length-1].kind!=='smoke') bad.push('control: the Smoke cell threw a '+g.throws[g.throws.length-1].kind);
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{
