         if(gz.player){ gz.player.cooking=0; gz.player.cookT=0; gz.player.cookKind=null; } } }catch(_e){}
       try{ var g4=__state(); if(g4&&!g4.over){ g4.player.downed=false; __endRaid('abandon'); } }catch(_e2){}
