       if(!p.wep||!p.wep.id||p.wep.id==='fists') return 'SKIP: no gun in hand at the drop';
       var gk='gun_'+p.wep.id; if(!ITEMS[gk]) return 'SKIP: no item for the gun in hand ('+gk+')';
       // THE ROOM: the gun in his hands bound to key 5, which blanks the derived cell 1.
       g.hotAssign={4:gk}; g.hotAuto={}; g.pouch.frag=0; g.pouch.smoke=0; g.pouch.decoy=0;
       p.ammo=Math.max(p.ammo||0,5); p.reloading=0; p.jam=0; p.cooking=0; p.fired=false; p.trigYield=0;
       p.wep.jam=0;   // the jam roll on the trigger pull would eat the shot this check counts; the raid ends before the gun is seen again
       var sl=hotbarSlots();
       // These two ARE the finding, so they fail rather than skip: a skip here
       // would quietly stop this check running the day the dedupe changed.
       if(!(sl[0]&&sl[0].kind==='empty')) bad.push('the premise is gone: binding the held gun to key 5 no longer blanks cell 1 (cell 1 is '+(sl[0]&&sl[0].kind)+')');
       if(!(sl[4]&&sl[4].kind==='gun')) bad.push('the premise is gone: key 5 did not take the held gun (cell 5 is '+(sl[4]&&sl[4].kind)+')');
       if(bad.length) return bad.join('; ');
       function press(frames){ mouse.down=true; for(var f=0;f<frames;f++) updatePlayer(0.016); }
       function release(){ mouse.down=false; updatePlayer(0.016); }
       // ARM A, THE RAID START: the highlight sits on the blank cell 1, as every raid begins.
       G.hot=0; p.fired=false; p.trigYield=0; p.lastShot=-9999; var sh0=g.tel.shots||0;
       window.__lastSay=null; press(1);
       if(hotSel()!==0) bad.push('a click on the blank cell 1 moved the highlight to cell '+(hotSel()+1)+'; since v13.42 he brings the gun up himself');
       if(String(window.__lastSay||'').indexOf('Press 5')<0) bad.push('a click on the blank cell 1 did not name key 5, the cell that holds his gun (said: '+String(window.__lastSay||'')+')');
       press(2); release();
       p.lastShot=-9999; press(2); release();
       if((g.tel.shots||0)!==sh0) bad.push('clicking the blank cell 1 fired the gun '+((g.tel.shots||0)-sh0)+' time(s)');
       // ARM B, THE v12.08 YIELD: an empty throwable cell selected; the yield must land on the gun cell, not the blank.
       var fi=-1; sl=hotbarSlots(); for(i=0;i<sl.length;i++) if(sl[i]&&sl[i].kind==='throw'&&!((sl[i].count|0)>0)){ fi=i; break; }
       if(fi<0) bad.push('staging: no empty throwable cell on the belt');
       else {
         G.hot=fi; p.fired=false; p.trigYield=0; p.cooking=0; var sh1=g.tel.shots||0;
         window.__lastSay=null; press(1);
         if(hotSel()!==fi) bad.push('a click on the empty throwable cell moved the highlight to cell '+(hotSel()+1)+'; since v13.42 he brings the gun up himself');
         if(String(window.__lastSay||'').indexOf('Press 5')<0) bad.push('the empty throwable cell did not name key 5 for the gun (said: '+String(window.__lastSay||'')+')');
         press(2); release();
         p.lastShot=-9999; press(2); release();
         if((g.tel.shots||0)!==sh1) bad.push('clicking the empty throwable cell fired the gun '+((g.tel.shots||0)-sh1)+' time(s)');
       }
       // ARM C, THE SECOND FALL-BACK: spending the LAST of a stack falls back the
       // same way. One bandage on key 4, selected, one click uses it and empties
       // the cell, and the fall-back must land on the gun and not on the blank.
       g.bag=['bandage']; g.hotAssign={3:'bandage',4:gk}; g.hotAuto={};
       var slc=hotbarSlots();
       if(!(slc[3]&&slc[3].assigned&&slc[3].itemKey==='bandage'&&(slc[3].count|0)===1)) bad.push('staging: key 4 is not a Bandage cell holding exactly one (kind '+(slc[3]&&slc[3].kind)+', count '+(slc[3]&&slc[3].count)+')');
       else {
         G.hot=3; p.fired=false; p.trigYield=0; p.hp=40; var sh2=g.tel.shots||0;
         press(1); release();
         if(g.bag.indexOf('bandage')>=0) bad.push('control: the click did not spend the last Bandage');
         else if(hotSel()!==3) bad.push('spending the last Bandage moved the highlight to cell '+(hotSel()+1)+'; since v13.42 it stays on the Bandage cell');
         p.lastShot=-9999; press(2); release(); press(2); release();
         if((g.tel.shots||0)!==sh2) bad.push('clicking on after the last Bandage fired the gun '+((g.tel.shots||0)-sh2)+' time(s)');
       }
     }catch(err){ bad.push('threw: '+(err&&err.message||err)); }
     finally{ try{ mouse.down=false; }catch(_m){} try{ var g2=__state(); if(g2&&!g2.over){ g2.player.downed=false; __endRaid('extract'); } }catch(_e){} __topClear(); __cleanProfile(); }
     return bad.length?bad.join('; '):null; }},
  {v:'12.30',what:'a crawler that reaches a still player bites inside a second and a half, carrying whatever wander clock the game rolled for it; a crawler already chasing with a clear cooldown bites inside 0.6 s; and a crawler wandering out of sight still wanders with its bite cooldown left clear (2026-09-07 audit P1, his standing crawler note)',
   run:function(){
     if(!(window.__deploy&&window.__state&&window.__endRaid&&window.__ents)) return 'SKIP: this fixture cannot deploy and step';
     if(typeof losClear!=='function'||typeof spotFree!=='function') return 'SKIP: no sight or placement test in this build';
     var bad=[];
     try{
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       var g=__state(), p=g.player, i, e=null;
       for(i=0;i<g.ents.length;i++) if(g.ents[i].kind==='crawler'){ e=g.ents[i]; break; }
       if(!e) return 'SKIP: no crawler on this map';
       for(i=g.ents.length-1;i>=0;i--) if(g.ents[i]!==e) g.ents.splice(i,1);   // only the crawler moves in this room
       p.downed=false; p.crouch=false; p.iv=0; g.crouchTog=false; keys={};
       if(typeof refreshVseg==='function') refreshVseg();
       function findSpot(r){
         var a, sx, sy;
         for(a=0;a<24;a++){ var ang=a*Math.PI/12; sx=p.x+Math.cos(ang)*r; sy=p.y+Math.sin(ang)*r; if(spotFree(g.map,sx,sy,24)&&losClear(sx,sy,p.x,p.y,g.vseg)) return {x:sx,y:sy}; }
         return null;
       }
       var near=findSpot(25);
       if(!near) return 'SKIP: no clear spot 25 units from the drop, so nothing can be parked in bite range';
       function park(st){
         e.x=near.x; e.y=near.y; e.path=null; e.pathGoal=null; e.chaseHold=0; e.alert=0;
         e.state=st; e.role=null; e.roleT=0; e.beat=0; e.cd=0; e.wanderT=0;
         e.tx=e.x; e.ty=e.y; e.face=Math.atan2(p.y-e.y,p.x-e.x);
         p.hp=100; p.armor=0; p.iv=0; p.downed=false;
       }
       function bite(maxF){
         var hp0=p.hp+(p.armor||0), f;
         for(f=0;f<maxF;f++){ __ents(1/60); if(p.hp+(p.armor||0)<hp0) return (f+1)/60; }
         return -1;
       }
       // ARM ONE, THE FINDING. Nothing is staged on the clock: the crawler is put
       // on patrol in bite range of a still man, and the game rolls its own wander
       // on the first idle frame, which is the roll he meets in a raid.
       park('patrol');
       var tA=bite(300);
       if(tA<0) bad.push('a crawler on patrol 25 units from a still man never bit him in 5 s (it ended '+e.state+' at '+Math.round(dist(e,p))+' units, cooldown '+(e.cd||0).toFixed(1)+')');
       else if(tA>1.5) bad.push('a crawler that reached a still man took '+tA.toFixed(1)+' s to bite him, which is the wander clock it was carrying and not the walk');
       // ARM TWO, THE RULER. Already chasing, cooldown clear: this room must be
       // able to produce a bite quickly, or the deadline above proves nothing.
       park('chase'); e.alert=2.4; e.tx=p.x; e.ty=p.y;
       var tB=bite(300);
       if(tB<0||tB>0.6) bad.push('control: a crawler already chasing with a clear cooldown took '+(tB<0?'more than 5':tB.toFixed(1))+' s to bite from 25 units, so this room cannot measure a first bite and arm one proves nothing');
       // ARM THREE: the wander still runs, and it no longer leaves anything on the
       // bite cooldown. Far away and out of his sight, so nothing chases.
       var far=findSpot(900)||findSpot(700);
       if(!far) bad.push('staging: no clear spot far enough out to watch a wander');
       else {
         e.x=far.x; e.y=far.y; e.state='patrol'; e.cd=0; e.wanderT=0; e.alert=0;
         e.tx=e.x; e.ty=e.y; e.path=null; e.pathGoal=null;
         var wx=e.x, wy=e.y;
         for(i=0;i<360;i++) __ents(1/60);
         var moved=Math.sqrt((e.x-wx)*(e.x-wx)+(e.y-wy)*(e.y-wy));
         if(moved<60) bad.push('a crawler left to wander for 6 s moved '+Math.round(moved)+' units, so the wander itself is broken');
         if((e.cd||0)>0.05) bad.push('after 6 s of wandering the crawler carries '+(e.cd||0).toFixed(1)+' s on its bite cooldown, which is the wander clock sitting in the field the bite reads');
       }
     }catch(err){ bad.push('threw: '+(err&&err.message||err)); }
     finally{ keys={}; try{ var g2=__state(); if(g2&&!g2.over){ g2.player.downed=false; __endRaid('extract'); } }catch(_e){} __topClear(); __cleanProfile(); }
     return bad.length?bad.join('; '):null; }},
  {v:'12.29',what:'a fresh profile opens on Few machines and a Light extraction, the two Settings rows draw those words as their own default rather than in the changed colour, and the world the corpus measures is unmoved (his order of 2026-09-08)',
   run:function(){
     if(typeof GAMEOPTS==='undefined'||typeof DEF==='undefined'||typeof gameOptLive!=='function') return 'SKIP: this build has no Settings table to read';
     if(!window.__resetCfg||!window.__pinDefaults) return 'SKIP: this fixture cannot reset the dials';
     var bad=[], i, row, ix;
     function rowOf(k){ for(i=0;i<GAMEOPTS.length;i++) if(GAMEOPTS[i].k===k) return GAMEOPTS[i]; return null; }
     try{
       __topClear(); __cleanProfile();
       // A FRESH PROFILE IS WHAT DEF SAYS, so the dials are reset to it and read back.
       __resetCfg();
       if(CFG.nSentry!==12) bad.push('a fresh profile starts on '+CFG.nSentry+' sentries, not the 12 that Machines Few carries');
       if(CFG.nCrawler!==20) bad.push('a fresh profile starts on '+CFG.nCrawler+' crawlers, not the 20 that Machines Few carries');
       if(CFG.crawlerPerHouse!==0) bad.push('a fresh profile floors crawlers at '+CFG.crawlerPerHouse+' a house; since v13.43 Machines Few carries 0, so Few means the count it names');
       if(CFG.siegeVol!==0.6) bad.push('a fresh profile starts on a siege volume of '+CFG.siegeVol+', not the 0.6 that Heat Light carries');
       // THE ROW HAS TO AGREE: the live dials must land ON the option, and that
       // option must be the row's own default, or the button draws in the colour
       // that means he has changed something.
       row=rowOf('robots'); ix=gameOptLive('robots');
       if(!row) bad.push('there is no Machines row to read');
       else{
         if(ix<0||!row.opts[ix]) bad.push('with a fresh profile the Machines row matches no option at all and would read CUSTOM');
         else if(row.opts[ix].n!=='Few') bad.push('with a fresh profile the Machines row reads '+row.opts[ix].n+' and not Few');
         if(ix>=0&&ix!==row.def) bad.push('the Machines row is on '+(row.opts[ix]?row.opts[ix].n:ix)+' but calls option '+row.def+' its default, so the button draws in the changed colour on a profile nobody has touched');
       }
       row=rowOf('ext'); ix=gameOptLive('ext');
       if(!row) bad.push('there is no extraction heat row to read');
       else{
         if(ix<0||!row.opts[ix]) bad.push('with a fresh profile the extraction heat row matches no option at all and would read CUSTOM');
         else if(row.opts[ix].n!=='Light') bad.push('with a fresh profile the extraction heat row reads '+row.opts[ix].n+' and not Light');
         if(ix>=0&&ix!==row.def) bad.push('the extraction heat row is on '+(row.opts[ix]?row.opts[ix].n:ix)+' but calls option '+row.def+' its default');
       }
       // AND THE CORPUS STILL MEASURES THE OLD WORLD, which is what the harness
       // pin is for: this is the guard on the change I had to make to the harness.
       __pinDefaults(0);
       if(CFG.nSentry!==20||CFG.nCrawler!==34||CFG.crawlerPerHouse!==2.5) bad.push('control: after the harness pin the world is '+CFG.nSentry+'/'+CFG.nCrawler+'/'+CFG.crawlerPerHouse+' and not the 20/34/2.5 every fingerprint in this corpus was measured on');
     }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
     finally{ try{ __resetCfg(); }catch(_c){} __topClear(); __cleanProfile(); }
     return bad.length?bad.join('; '):null; }},
  {v:'12.28',what:'a Peddler purchase says where it went: a bought rifle names the belt key autoBelt pinned it to, a medkit with no key set says In your backpack, and a medkit on key 6 says key 6, with the credits falling by the prices (his note of 2026-09-07: purchases did not show up in the inventory)',
   run:function(){
     if(!(window.__deploy&&window.__state&&window.__endRaid&&window.__P)) return 'SKIP: this fixture cannot deploy';
     if(typeof mkPeddler!=='function'||typeof pedBuy!=='function') return 'SKIP: no Peddler in this build';
     var bad=[], P2=__P(), keepC=P2.credits, keepSec=P2.equippedSec, keepEq=P2.equipped, keepW=(P2.weapons||[]).slice();
     try{
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       // PIN THE SECOND HAND TOO. __pinDefaults pins the primary to the SMG and
       // never names the sidearm, and autoBelt refuses to pin a bought gun that
       // is already in either hand (the v8.04 dedupe). A profile carrying the
       // Auto Rifle as its sidearm would therefore make this check go red for a
       // reason that is his loadout and not the build.
       P2.equippedSec='none'; saveProfile();
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       var g=__state(), p=g.player;
       var pd=mkPeddler(p.x+40,p.y,g.map);
       pd.stock=[{k:'gun_rifle',price:10,sold:false},{k:'medkit',price:20,sold:false},{k:'medkit',price:30,sold:false}];
       g.trade=pd; g.hotAssign={}; g.hotAuto={}; g.bag=[];
       P2.credits=5000;
       // THE RIFLE: autoBelt pins it to the first free belt cell, so the line must name that key.
       g.msg=''; pedBuy(0);
       var m1=g.msg||'';
       if(m1.indexOf('Bought')<0) bad.push('control: the rifle purchase did not say Bought (said "'+m1+'")');
       var onBelt=false; for(var bi in (g.hotAssign||{})) if(g.hotAssign[bi]==='gun_rifle') onBelt=true;
       if(!onBelt) bad.push('staging: autoBelt did not pin the bought rifle to a belt cell, so the line has no key to name');
       else if(!/tactical belt, key [1-9]/.test(m1)) bad.push('the rifle line said "'+m1+'" and not which belt key it went to');
       if(g.bag.indexOf('gun_rifle')<0) bad.push('control: the bought rifle is not in the bag');
       // THE MEDKIT WITH NO KEY SET: the backpack.
       g.msg=''; pedBuy(1);
       var m2=g.msg||'';
       if(!/In your backpack/.test(m2)) bad.push('a medkit bought with no key set said "'+m2+'" and not In your backpack');
       // THE MEDKIT ON KEY 6.
       g.hotAssign[5]='medkit'; g.msg=''; pedBuy(2);
       var m3=g.msg||'';
       if(!/tactical belt, key 6/.test(m3)) bad.push('a medkit bought with key 6 set to medkit said "'+m3+'" and not key 6');
       // THE PURCHASE ITSELF, unchanged: the credits fell by the three prices.
       if(P2.credits!==5000-60) bad.push('control: credits are '+P2.credits+' after three purchases priced 10, 20 and 30 from 5000');
     }catch(err){ bad.push('threw: '+(err&&err.message||err)); }
     finally{
       // The raid ends FIRST: endRaid pays the credits out and re-sorts the two
       // gun slots, so anything put back before it runs is overwritten by it.
       try{ var g2=__state(); if(g2&&!g2.over){ g2.trade=null; g2.player.downed=false; __endRaid('abandon'); } }catch(_e){}
       P2.credits=keepC; P2.equippedSec=keepSec; P2.equipped=keepEq; P2.weapons=keepW;
       try{ saveProfile(); }catch(_s){}
       __topClear(); __cleanProfile();
     }
     return bad.length?bad.join('; '):null; }},
  {v:'12.27',what:'a stash drop onto the backpack for an item bound to a key with nothing packed lands on that key with a count and words, a bound key with nothing packed shows a 0 on the plan, and a spent belt key in a raid says No Bandage left (his note of 2026-09-07: bandages did not come over)',
   run:function(){
     if(!(window.__P&&window.__hubEnter&&window.__showScreen&&window.__deploy&&window.__state&&window.__endRaid)) return 'SKIP: this fixture cannot reach the stash screen and a raid';
     if(typeof renderHub!=='function'||typeof packedCount!=='function'||typeof useHot!=='function'||typeof hotbarSlots!=='function') return 'SKIP: this build has no belt plan to measure';
     var bad=[], P2=__P(), keep={stash:(P2.stash||[]).slice(),kit:(P2.kit||[]).slice(),hot:JSON.parse(JSON.stringify(P2.hotAssign||{})),freeKit:P2.freeKit};
     function zeroOn(cell){ var sp=cell.querySelectorAll('span'), i; for(i=0;i<sp.length;i++) if((sp[i].textContent||'').trim()==='0') return true; return false; }
     try{
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       try{ var g0=__state(); if(g0&&!g0.over){ g0.player.downed=false; __endRaid('abandon'); } }catch(_0){}
       keys={}; __showScreen('hub'); __hubEnter();
       // A key left on Bandage by the last raid (dropDeadKeys keeps it while the stash has one), nothing packed, three in the stash.
       P2.stash=['bandage','bandage','bandage','wire']; P2.kit=[]; P2.hotAssign={2:'bandage'}; P2.freeKit=0; saveProfile();
       renderHub();
       var hub=document.getElementById('hub'); if(hub) hub.classList.add('on');
       // (B) the plan cell for key 3 says 0.
       var cell=document.querySelector('#hub [data-plan="2"]');
       if(!cell) bad.push('staging: no plan cell for key 3 on the stash screen');
       else if(!zeroOn(cell)) bad.push('the plan cell for key 3, set to Bandage with none packed, shows no 0');
       // (A) the drop, through the real pointer dropzone handler.
       var col=document.getElementById('kitcol');
       if(!col||typeof col.__grabDrop!=='function') return 'SKIP: the backpack column takes no pointer drop';
       HUBSAY=''; col.__grabDrop('bandage','stash');
       var nb=packedCount('bandage'), kn=document.getElementById('kitn'), shown=kn?parseInt(kn.textContent,10):-1;
       if(nb<1) bad.push('the drop packed nothing');
       if(!(shown>0)) bad.push('after the drop the backpack column shows '+shown+' items: the Bandage vanished into the key');
       if(!/key 3/.test(HUBSAY||'')) bad.push('the drop said "'+(HUBSAY||'')+'" and not which key took it');
       var c2=document.querySelector('#hub [data-plan="2"]');
       if(c2&&nb>1&&(c2.textContent||'').indexOf('x'+nb)<0) bad.push('the plan cell does not show x'+nb+' after the drop (it reads "'+(c2.textContent||'').trim()+'")');
       // CONTROL: the same drop with no key bound packs one copy, as it always has.
       P2.kit=[]; P2.hotAssign={}; saveProfile(); renderHub(); col.__grabDrop('wire','stash');
       if(packedCount('wire')!==1) bad.push('control: a drop with no key bound packed '+packedCount('wire')+' copies, not one');
       if(hub) hub.classList.remove('on');
       // (C) in a raid, a key on a Bandage with none in the bag says so.
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       var g=__state();
       g.hotAssign={2:'bandage'}; g.hotAuto={}; g.bag=[]; g.msg=''; g.hot=2;
       var sl=hotbarSlots(), s2=sl[2];
       if(!(s2&&s2.assigned&&s2.itemKey==='bandage')) bad.push('staging: belt cell 3 is not the assigned Bandage cell (kind '+(s2&&s2.kind)+')');
       useHot();
       if(!/No Bandage left/.test(g.msg||'')) bad.push('a spent Bandage key said "'+(g.msg||'')+'", not No Bandage left');
     }catch(err){ bad.push('threw: '+(err&&err.message||err)); }
     finally{
       try{ var g2=__state(); if(g2&&!g2.over){ g2.player.downed=false; __endRaid('abandon'); } }catch(_e){}
       P2.stash=keep.stash; P2.kit=keep.kit; P2.hotAssign=keep.hot; P2.freeKit=keep.freeKit;
       try{ saveProfile(); }catch(_s){}
       try{ var hb2=document.getElementById('hub'); if(hb2) hb2.classList.remove('on'); }catch(_h){}
       __topClear(); __cleanProfile();
     }
     return bad.length?bad.join('; '):null; }},
  {v:'12.26',what:'taking the freebie kit at the stash and then confirming FREEBIE KIT at the lift keeps the record of what he had packed, and a run that ends dead leaves that gear in his stash with an empty backpack and belt and a card that says so (his note of 2026-09-07 built it, his note of 2026-09-11 reversed what comes back)',
   run:function(){
     if(!(window.__startRaid&&window.__state&&window.__endRaid&&window.__P&&window.__hubEnter&&window.__showScreen)) return 'SKIP: this fixture cannot start a raid';
     if(typeof askKit!=='function'||typeof commitKit!=='function'||typeof renderFreeKit!=='function'||typeof ascendNow!=='function') return 'SKIP: this fixture cannot reach the lift question';
     var bad=[], P2=__P();
     var keep={stash:(P2.stash||[]).slice(),kit:(P2.kit||[]).slice(),hot:JSON.parse(JSON.stringify(P2.hotAssign||{})),freeKit:P2.freeKit,kitSaved:P2.kitSaved,kbf:P2.kitBeforeFree,chosen:P2.kitChosen,drop:(P2.dropKit||[]).slice(),weapons:(P2.weapons||[]).slice(),eq:P2.equipped,safe:P2.safe,gun:P2._gunSlot};
     var _asc=ascendNow, alt=null;
     try{
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       try{ var g0=__state(); if(g0&&!g0.over){ g0.player.downed=false; __endRaid('abandon'); } }catch(_0){}
       keys={}; __showScreen('hub'); __hubEnter();
       // DISTINCTIVE: three items no fallback packs together, one of them on a key.
       P2.stash=['smoke','decoy','wire','medkit','bandage']; P2.kit=['smoke','decoy','wire']; P2.hotAssign={3:'smoke'}; P2.safe=null;
       P2.freeKit=0; P2.kitSaved=null; P2.kitBeforeFree=null; P2.kitChosen=0; P2.weapons=['pistol']; P2.equipped='fists'; saveProfile();
       // STEP ONE: the stash button takes the freebie kit, for real.
       renderFreeKit(); var fb=document.querySelector('.fkbtn');
       if(!fb||!fb.onclick) return 'SKIP: the freebie kit button was not drawn';
       fb.onclick();
       if(!P2.freeKit) bad.push('staging: the stash button did not take the kit');
       if(!(P2.kitSaved&&P2.kitSaved.kit&&P2.kitSaved.kit.length===3)) bad.push('staging: the stash button did not keep the three items aside');
       // STEP TWO: the lift asks, and he answers FREEBIE KIT again.
       askKit(); alt=ASKALT;
       if(typeof alt!=='function') return 'SKIP: the lift question offers no FREEBIE KIT answer';
       ascendNow=function(){ commitKit(); };
       alt();
       ascendNow=_asc;
       // THE FINDING: on v12.25 the answer re-snapshotted the emptied kit, so nothing was kept.
       var kb=(P2.kitBeforeFree||[]).slice().sort().join(',');
       if(kb!=='decoy,smoke,wire') bad.push('after FREEBIE KIT at the lift the packing kept for the restore is ['+kb+'], not the three items packed at the stash');
