  {v:'11.94',what:'the Crier names itself when its alarm goes out, the Pillbox says destroyed when it dies, and the self-revive says one per raid (his three wording notes of 2026-09-06)',
   run:function(){
     if(!(window.__deploy&&window.__state&&window.__endRaid&&window.__ents)) return 'SKIP: this fixture cannot deploy and step';
     if(typeof mkSnitch!=='function'||typeof mkListener!=='function'||typeof selfRevive!=='function'||typeof updatePlayer!=='function') return 'SKIP: a maker or verb is missing in this build';
     var bad=[], said=[], realSay=say;
     try{
       __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
       __deploy({kit:[],safe:null,mapIx:0,seed:4242});
       var g=__state(), p=g.player, i;
       say=function(m){ said.push(String(m)); return realSay.apply(null,arguments); };
       // ONE: the Crier, at the last instant of its alarm windup.
       for(i=0;i<g.ents.length;i++) if(g.ents[i].kind==='snitch') g.ents[i].hp=0;   // the map's own criers, out of the way
       var cr=mkSnitch(p.x+240,p.y); cr.state='alarm'; cr.wind=0.01; cr.markX=p.x; cr.markY=p.y; cr.lost=0; g.ents.push(cr);
       __ents(0.1);
       if(!said.some(function(t){ return t.indexOf('The Crier raised the alarm.')===0; })) bad.push('the alarm line does not name the Crier (said: '+said.filter(function(t){ return /larm/.test(t); }).join(' | ').slice(0,90)+')');
       if(said.some(function(t){ return t.indexOf('Alarm went out. It')===0||t.indexOf('Alarm went out. They')===0; })) bad.push('the old Alarm went out line still prints');
       // TWO: the Pillbox, destroyed.
       said.length=0;
       var L=mkListener(p.x+300,p.y+40); L.hp=0; g.ents.push(L);
       __ents(0.1);
       if(!said.some(function(t){ return /destroyed\. It has stopped listening/.test(t); })) bad.push('the Pillbox death line does not say destroyed (said: '+said.join(' | ').slice(0,90)+')');
       // THREE: the self-revive, spent and pressed, and the down line.
       said.length=0; p.downed=true; p.revived=true; selfRevive();
       if(!said.some(function(t){ return t==='Self-revive spent. One per raid.'; })) bad.push('the spent revive does not say one per raid (said: '+said.join(' | ').slice(0,90)+')');
       said.length=0; p.downed=false; p.revived=false; p.hp=5; p.armor=0; p.iv=0;
       damagePlayer(40,null,'crawler',p.x+20,p.y);
       if(!said.some(function(t){ return /You get one per raid\./.test(t); })) bad.push('the down line does not say one per raid (said: '+said.join(' | ').slice(0,90)+')');
       p.downed=false; p.hp=100;
       // FOUR: a container search picked up at six percent.
       var ct=null; for(i=0;i<g.containers.length&&!ct;i++) if(g.containers[i]&&g.containers[i].time>0&&!g.containers[i].done) ct=g.containers[i];
       if(!ct) bad.push('control: no searchable container on the map');
       else {
         p.x=ct.x+18; p.y=ct.y; ct.prog=ct.time*0.06; g.searching=null; g.searchT=0; keys={}; keys['KeyE']=true; said.length=0;
         updatePlayer(0.016);
         keys={};
         if(!said.some(function(t){ return t==='Search resumed, 6% done.'; })) bad.push('the resumed search does not say Search resumed (said: '+said.join(' | ').slice(0,90)+')');
       }
     }catch(err){ bad.push('threw: '+(err&&err.message||err)); }
     finally{ say=realSay; keys={}; try{ var g2=__state(); if(g2&&!g2.over){ g2.player.downed=false; g2.player.hp=100; g2.searching=null; __endRaid('extract'); } }catch(_e){} __topClear(); __cleanProfile(); }
     return bad.length?bad.join('; '):null; }},
  {v:'11.93',what:'ENTER in the title name box commits the name, and the start button commits whatever is typed there (2026-09-06 first-ten-minutes audit)',
   run:function(){
     var t=document.getElementById('title'), pin=document.getElementById('pnamein'), st=document.getElementById('titlestart');
     if(!t||!pin||!st) return 'SKIP: no title screen in this fixture';
     var bad=[], P2=__P(), keepName=P2.pname, wasOn=t.classList.contains('on');
     try{
       __topClear(); __runPrep();
       t.classList.add('on');
       pin.value='KESTREL 4242'; try{ pin.focus(); }catch(_f){}
       var focused=(document.activeElement===pin);   // a hidden pane may refuse focus; the blur is measured only when it took
       pin.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',code:'Enter',bubbles:true,cancelable:true}));
       if(P2.pname!=='KESTREL 4242') bad.push('ENTER in the box left the name as '+P2.pname);
       if(!t.classList.contains('on')) bad.push('control: ENTER in the box started the game');
       if(focused&&document.activeElement===pin) bad.push('ENTER committed the name but did not leave the box');
       // A SECOND ENTER, with the box left, starts the game.
       t.classList.add('on');
       window.dispatchEvent(new KeyboardEvent('keydown',{key:'Enter',code:'Enter',bubbles:true,cancelable:true}));
       if(t.classList.contains('on')) bad.push('a second ENTER after leaving the box did not start the game');
       t.classList.add('on');
       pin.value='MERLIN 4242';
       st.click();
       if(P2.pname!=='MERLIN 4242') bad.push('the start button left the name as '+P2.pname);
       if(t.classList.contains('on')) bad.push('control: the start button did not start the game');
     }catch(err){ bad.push('threw: '+(err&&err.message||err)); }
     finally{
       P2.pname=keepName; try{ pin.value=keepName||''; pin.blur(); }catch(_v){}
       try{ saveProfile(); }catch(_s){}
       t.classList.toggle('on',wasOn);
       try{ if(titleRefresh) titleRefresh(); }catch(_tr){}
       __topClear(); __cleanProfile();
     }
     return bad.length?bad.join('; '):null; }},
  {v:'11.92',what:'the NEW IN card greets only a player with runs behind him, and for him it fits the screen with its heading and its dismiss line both on the canvas (2026-09-06 first-ten-minutes audit)',
   run:function(){
     if(!(window.__wnseen&&window.__hubEnter&&window.__hubFrame&&window.__forceSize&&window.__showScreen)) return 'SKIP: this fixture cannot drive the floor card';
     if(window.__vpAlive&&!__vpAlive()) return 'SKIP: the pane has no layout, so nothing renders';
     var bad=[], P2=__P(), keepRuns=P2.runs, rec=[], proto=CanvasRenderingContext2D.prototype, o=proto.fillText;
     try{
       __topClear(); __runPrep(); __forceSize(1920,1080);
       if(!(H>400)) return 'SKIP: the canvas came back '+W+'x'+H+', too small to measure the card';
       G=null; keys={}; __showScreen('hub'); __hubEnter();
       proto.fillText=function(t,x,y){ rec.push({t:String(t),y:y}); return o.apply(this,arguments); };
       // ARM ONE: a profile with no runs never sees the card and stamps itself current.
       P2.runs=0; __wnseen(0); rec.length=0;
       __hubFrame(0.016); __hubFrame(0.016);
       if(rec.some(function(r){ return r.t.indexOf('NEW IN v')===0; })) bad.push('a profile with no runs was shown the card');
       if(__wnseen()!==1) bad.push('a profile with no runs did not stamp itself current');
       // ARM TWO: a returning player gets a card that fits.
       P2.runs=Math.max(1,keepRuns||0); __wnseen(0); rec.length=0;
       __hubFrame(0.016);
       var hd=null, dm=null, first=0;
       for(var i=0;i<rec.length;i++){
         if(!hd&&rec[i].t.indexOf('NEW IN v')===0) hd=rec[i];
         if(!dm&&/press ENTER or walk to dismiss/.test(rec[i].t)) dm=rec[i];
         if(/^2\. /.test(rec[i].t)) first++;   // the second row: the first is the pinned ALPHA notice, which the cut always keeps
       }
       if(!hd) bad.push('control: a returning player was not shown the card');
       else if(hd.y<0||hd.y>H) bad.push('the heading is drawn at y '+Math.round(hd.y)+' on a canvas '+H+' tall');
       if(!dm) bad.push('the dismiss line was not drawn');
       else if(dm.y<0||dm.y>H) bad.push('the dismiss line is drawn at y '+Math.round(dm.y)+' on a canvas '+H+' tall');
       if(!first) bad.push('the newest entry is not on the card');
     }catch(err){ bad.push('threw: '+(err&&err.message||err)); }
     finally{ proto.fillText=o; P2.runs=keepRuns; __wnseen(1); try{ saveProfile(); }catch(_s){} __topClear(); __cleanProfile(); }
     return bad.length?bad.join('; '):null; }},
