       fresh();
       __hubEnter();
       var no=document.getElementById('welcomeno');
       if(no){ no.onclick();
         var third=openIds();
         if(third.indexOf('welcomemodal')>=0) bad.push('closing the pack with CLOSE leaves it on the screen');
       }
       // 5. AND A RETURNING PLAYER IS NOT ASKED AGAIN. v10.88: steps 5 and 6
