       function maxGain(lg){ var m=0; lg.forEach(function(x){ var mm=/^gain[:=](-?\d+)$/.exec(x); if(mm) m=Math.max(m,+mm[1]); }); return m; }
       var S=['stone','wood','metal','leaf','water'], sigs={};
