  {v:'10.56',what:'every gun schedules its own voice, no two alike, each shot a little different from the last, and reload and dry fire schedule sounds of their own',
   run:function(){
     var bad=[];
     if(typeof _realBlip!=='function'||typeof WEAPONS==='undefined') return 'SKIP: this build has no real blip to trace';
     // A recording AudioContext: every node the synth builds is written down
     // with the numbers it was given, so what a shot IS can be compared without
     // anything being audible. The fixture blocks the real one.
     function param(v,log,name){ var o={value:v}; ['setValueAtTime','exponentialRampToValueAtTime','linearRampToValueAtTime','setTargetAtTime'].forEach(function(m){ o[m]=function(x){ log.push(name+':'+Math.round(x*100)); return o; }; }); return o; }
     function fake(){
       var L=[]; var node=function(kind,extra){ var o={kind:kind,connect:function(){ return o; },disconnect:function(){},start:function(){},stop:function(){}}; for(var k in extra) o[k]=extra[k]; return o; };
       var a={currentTime:0,sampleRate:48000,state:'running',destination:node('dest'),resume:function(){},
         log:L,
         createBuffer:function(ch,len){ L.push('buf:'+len); return {length:len,getChannelData:function(){ return new Float32Array(len); }}; },
         createBufferSource:function(){ var o=node('src'); o.buffer=null; return o; },
         createOscillator:function(){ var o=node('osc'); o.type='sine'; o.frequency=param(440,L,'osc'); o.detune=param(0,[],'det'); var st=o.start; o.start=function(){ L.push('osc:'+o.type); }; return o; },
         createBiquadFilter:function(){ var o=node('flt'); o.type='lowpass'; var fr=param(350,[],'f'); o.frequency={get value(){ return fr.value; }, set value(v){ fr.value=v; L.push('flt:'+o.type+':'+Math.round(v*100)); }, setValueAtTime:function(v){ L.push('flt:'+o.type+':'+Math.round(v*100)); }, exponentialRampToValueAtTime:function(v){ L.push('fltr:'+Math.round(v*100)); }, linearRampToValueAtTime:function(v){ L.push('fltr:'+Math.round(v*100)); }, setTargetAtTime:function(v){ L.push('fltr:'+Math.round(v*100)); }}; o.Q=param(1,[],'q'); return o; },
         createGain:function(){ var o=node('gain'); o.gain=param(1,[],'g'); return o; },
         createStereoPanner:function(){ var o=node('pan'); o.pan=param(0,[],'p'); return o; },
         createDelay:function(){ var o=node('dly'); o.delayTime=param(0,[],'d'); return o; }
       };
       return a;
     }
     var keepAC=AC, keepBUS=BUS, keepSim=(G?G.sim:null);
     var guns=Object.keys(WEAPONS).filter(function(k){ return WEAPONS[k].mag>0; });
     try{
       if(G) G.sim=false;   // blip is silent in a sim raid, and an earlier check may have left one
       var a=fake(); AC=a; BUS=a.createGain();
       function shot(id){ a.log.length=0; _realBlip('shot',0,undefined,id); return a.log.slice(); }
       function sig(log){ return log.filter(function(x){ return (/^(buf|flt|osc):/).test(x); }).map(function(x){ return x.replace(/:(\d+)$/,function(m,d){ return ':'+Math.round(+d/25)*25; }); }).join('|'); }
       var sigs={};
       for(var i=0;i<guns.length;i++){
         var lg=shot(guns[i]);
         if(!lg.length){ bad.push(WEAPONS[guns[i]].name+' schedules nothing'); continue; }
         var sg=sig(lg);
         for(var j in sigs) if(sigs[j]===sg) bad.push(WEAPONS[guns[i]].name+' and '+WEAPONS[j].name+' schedule the same voice');
         sigs[guns[i]]=sg;
         // Jitter: two shots of one gun differ somewhere, and stay within reach of each other.
         var lg2=shot(guns[i]);
         if(lg.join('|')===lg2.join('|')) bad.push(WEAPONS[guns[i]].name+' fires the identical waveform twice');
         var n1=lg.map(function(x){ return +(x.split(':').pop()); }), n2=lg2.map(function(x){ return +(x.split(':').pop()); });
         if(n1.length!==n2.length) bad.push(WEAPONS[guns[i]].name+' schedules a different number of nodes shot to shot');
         else for(var q=0;q<n1.length;q++){ if(n1[q]>50&&Math.abs(n1[q]-n2[q])>n1[q]*0.15){ bad.push(WEAPONS[guns[i]].name+' drifts more than 15% shot to shot ('+lg[q]+' vs '+lg2[q]+')'); break; } }
       }
       a.log.length=0; _realBlip('reload'); if(a.log.filter(function(x){ return (/^(buf|osc):/).test(x); }).length<2) bad.push('a reload schedules '+a.log.length+' nodes');
       a.log.length=0; _realBlip('reloadin'); if(!a.log.length) bad.push('a finished reload schedules nothing');
       a.log.length=0; _realBlip('dry'); if(!a.log.length) bad.push('a dry pull schedules nothing');
     } finally { AC=keepAC; BUS=keepBUS; if(G&&keepSim!==null) G.sim=keepSim; }
     return bad.length?bad.join('; '):null; }},
  {v:'10.55',what:'footprints follow ground covered: evenly spaced in the open at a walk and a sprint, none while pinned against a wall, none inside a wall',
   run:function(){
     var bad=[];
     if(!(window.__startRaid&&window.__loop)) return 'SKIP: this build cannot run the live loop';
     __startRaid({seed:4242,mapIx:0});
     if(!G||!G.player||!G.map) return 'no raid';
     var p=G.player, K=keys;
     for(var k in K) K[k]=false;
     var keep={x:p.x,y:p.y,tog:G.sprintTog,stam:p.stam,printAcc:p.printAcc,decals:G.decals};
     function mine(){ return G.decals.filter(function(d){ return d.print&&d.mine; }); }
     function inWall(x,y){ var W=G.map.walls; for(var i=0;i<W.length;i++){ var w=W[i]; if(x>w.x&&x<w.x+w.w&&y>w.y&&y<w.y+w.h) return true; } return false; }
     function clearOf(x,y,r){ var W=G.map.walls; for(var i=0;i<W.length;i++){ var w=W[i]; if(x+r>w.x&&x-r<w.x+w.w&&y+r>w.y&&y-r<w.y+w.h) return false; } return true; }
     // A stretch of open floor: scan right from a wall-free spot for 260 units of clearance.
     function openSpot(){
       var W=G.map.walls;
       for(var t=0;t<4000;t++){
         var x=200+((t*977)%(WORLD_W-400)), y=200+((t*613)%(WORLD_H-400));
         var ok=true; for(var s=0;s<=260&&ok;s+=20) if(!clearOf(x+s,y,16)||inWater(x+s,y)) ok=false;
         if(ok) return {x:x,y:y};
       }
       return null;
     }
     var t=performance.now();
     function run(frames){ for(var i=0;i<frames;i++){ t+=16.7; __loop(t); } }
     try{
       var sp=openSpot(); if(!sp) return 'SKIP: no 260 unit open stretch found on this map';
       // 1. A walk across open ground: prints evenly spaced.
       G.decals=[]; p.x=sp.x; p.y=sp.y; p.printAcc=0; p.stam=100; G.sprintTog=false;
       K['KeyD']=true; run(70); K['KeyD']=false;
       var pw=mine(), gaps=[];
       for(var i=1;i<pw.length;i++) gaps.push(Math.hypot(pw[i].x-pw[i-1].x,pw[i].y-pw[i-1].y));
       if(pw.length<2) bad.push('a 70 frame walk left '+pw.length+' prints');
       for(i=0;i<gaps.length;i++) if(gaps[i]<48||gaps[i]>64){ bad.push('walking prints are '+gaps[i].toFixed(1)+' apart, not about 56'); break; }
       // 2. A sprint across open ground: the same spacing.
       G.decals=[]; p.x=sp.x; p.y=sp.y; p.printAcc=0; p.stam=100; G.sprintTog=true;
       K['KeyD']=true; run(45); K['KeyD']=false;
       var ps=mine(), gs=[];
       for(i=1;i<ps.length;i++) gs.push(Math.hypot(ps[i].x-ps[i-1].x,ps[i].y-ps[i-1].y));
       if(ps.length<2) bad.push('a 45 frame sprint left '+ps.length+' prints');
       for(i=0;i<gs.length;i++) if(gs[i]<48||gs[i]>64){ bad.push('sprinting prints are '+gs[i].toFixed(1)+' apart, not about 56'); break; }
       // 3. Pinned against a wall, sprinting into it: no prints, and none inside the wall.
       // A wall that actually stops him: tried, not assumed, because a window,
       // a door or a piece of furniture is in the same list and lets him through.
       var wall=null; var W=G.map.walls;
       for(i=0;i<W.length&&!wall;i++){
         var w=W[i];
         if(!(w.h>=40&&w.w>=8&&clearOf(w.x-40,w.y+w.h/2,14)&&!inWater(w.x-40,w.y+w.h/2))) continue;
         p.x=w.x-p.r-0.5; p.y=w.y+w.h/2; G.sprintTog=false; p.stam=100;
         var tx=p.x; K['KeyD']=true; run(6); K['KeyD']=false;
         if(Math.abs(p.x-tx)<1) wall=w;
       }
       if(!wall) return 'SKIP: no wall on this map stops him from the left';
       G.decals=[]; p.x=wall.x-p.r-0.5; p.y=wall.y+wall.h/2; p.printAcc=0; p.stam=100; G.sprintTog=true;
       var x0=p.x; K['KeyD']=true; run(120); K['KeyD']=false; G.sprintTog=false;
       var pp=mine();
       if(Math.abs(p.x-x0)>1) bad.push('he was not pinned: moved '+(p.x-x0).toFixed(1));
       else if(pp.length>1) bad.push('pinned against a wall, sprinting into it for 120 frames, he stamped '+pp.length+' prints under himself');
       for(i=0;i<pp.length;i++) if(inWall(pp[i].x,pp[i].y)){ bad.push('a print was stamped inside a wall'); break; }
     } finally {
       for(var k2 in K) K[k2]=false;
       p.x=keep.x; p.y=keep.y; G.sprintTog=keep.tog; p.stam=keep.stam; p.printAcc=keep.printAcc; G.decals=keep.decals;
     }
     return bad.length?bad.join('; '):null; }},
  {v:'10.54',what:'the OUTFIT rack exists, each suit repaints the whole figure and hides the coat colour, an unowned suit changes nothing, and the Depot lists the slot',
   run:function(){
     var bad=[];
     if(typeof drawOp!=='function'||typeof cosWorn!=='function'||typeof COSMETICS==='undefined') return 'SKIP: no painter or racks in this build';
     var P2=__P();
     var keep={all:P2.cosAll,out:P2.cosOutfit,fit:P2.cosFit,slot:P2._avSlot};
     function paint(){
       var c=document.createElement('canvas'); c.width=200; c.height=320;
       var g=c.getContext('2d'); var keepWc=wc; wc=g;
       try{ g.save(); g.translate(100,304); g.scale(5.2,5.2);
            drawOp(0,0,0,0,'#242832',0,0,'none',0,{hero:1,moving:false,sprint:false,ads:false,hurt:0,rl:0,own:{wep:null}});
            g.restore(); }
       finally { wc=keepWc; }
       return g.getImageData(0,0,200,320).data;
     }
     function differ(a,b){ var d=0; for(var j=0;j<a.length;j+=4) if(a[j]!==b[j]||a[j+1]!==b[j+1]||a[j+2]!==b[j+2]) d++; return d; }
     function countCol(a,r,g,b){ var d=0; for(var j=0;j<a.length;j+=4) if(Math.abs(a[j]-r)<=2&&Math.abs(a[j+1]-g)<=2&&Math.abs(a[j+2]-b)<=2) d++; return d; }
     try{
       var suits=COSMETICS.filter(function(c){ return c.kind==='outfit'&&c.id!=='outnone'; });
       if(suits.length<7) bad.push('the OUTFIT rack holds '+suits.length+' suits, not seven');
       if(typeof LOOK_KINDS==='undefined'||LOOK_KINDS.indexOf('outfit')<0) bad.push('a look does not carry the outfit');
       // 1. Unowned: a fresh profile wearing a suit it has not earned paints its own clothes.
       P2.cosAll=false; P2.cosFit='slate'; P2.cosOutfit='outnone';
       // A fresh profile for this pair of paints: the counters are lent back to
       // zero so nothing is owned, then both figures are painted under the same
       // racks and only the outfit differs between them.
       var lend={runs:P2.runs,ext:P2.ext,lvl:P2.xpLevel,kills:P2.kills};
       P2.runs=0; P2.ext=0; P2.xpLevel=1; P2.kills={};
       var fresh=paint();
       var stillOwned=cosOwned(cosFind('outskeleton'));
       P2.cosOutfit='outskeleton';
       var unowned=paint();
       P2.runs=lend.runs; P2.ext=lend.ext; P2.xpLevel=lend.lvl; P2.kills=lend.kills;
       P2.cosOutfit='outnone';
       var base=paint();
       if(stillOwned) bad.push('a fresh profile owns the Skeleton without earning it');
       else if(differ(fresh,unowned)!==0) bad.push('an unowned suit repainted '+differ(fresh,unowned)+' pixels');
       // 2. Owned: every suit repaints the figure and hides the slate coat.
       P2.cosAll=true;
       var slateN=countCol(base,0x59,0x62,0x6f);
       if(slateN<40) bad.push('the control figure shows only '+slateN+' slate coat pixels, so the coat test would prove nothing');
       for(var i=0;i<suits.length;i++){
         P2.cosOutfit=suits[i].id;
         var px=paint(), d=differ(base,px), sl=countCol(px,0x59,0x62,0x6f);
         if(d<300) bad.push(suits[i].name+' changes only '+d+' pixels of the figure');
         if(sl>0) bad.push(suits[i].name+' still shows '+sl+' pixels of the slate coat');
       }
       P2.cosOutfit='outtrooper';
       if(countCol(paint(),0x3f,0x6a,0x3a)<30) bad.push('the Trooper paints no helmet green');
       // 3. The Depot lists the slot, first.
       P2.cosOutfit='outnone'; P2._avSlot=null;
       if(typeof renderAvatar==='function'&&document.getElementById('appavatar')){
         renderAvatar('appavatar','appavatarpicker');
         var slots=document.querySelectorAll('#appavatar [data-av]');
         if(!slots.length||slots[0].getAttribute('data-av')!=='outfit') bad.push('the Depot does not list OUTFIT as its first slot');
         var tiles=document.querySelectorAll('#appavatarpicker .costile[data-kind="outfit"]');
         if(tiles.length<8) bad.push('the Depot racks show '+tiles.length+' outfit tiles, not eight');
       } else bad.push('the Depot is not on this page');
     } finally {
       P2.cosAll=keep.all; P2.cosOutfit=keep.out||'outnone'; P2.cosFit=keep.fit; P2._avSlot=keep.slot;
       try{ saveProfile(); }catch(_sv){}
     }
     return bad.length?bad.join('; '):null; }},
  {v:'10.53',what:'the cheat box ALL COSMETICS switch opens every rack when on, returns exactly the earned racks when off, and touches nothing earned or bought',
   run:function(){
     var bad=[];
     if(typeof cosOwned!=='function'||typeof renderCheat!=='function'||typeof COSMETICS==='undefined') return 'SKIP: no racks or cheat box in this build';
     var P2=__P();
     var keepAll=P2.cosAll, keepBought=JSON.stringify(P2.cosBought||{}), keepRuns=P2.runs, keepExt=P2.ext;
     function owned(){ var n=0; for(var i=0;i<COSMETICS.length;i++) if(cosOwned(COSMETICS[i])) n++; return n; }
     try{
       P2.cosAll=false;
       var base=owned();
       if(base>=COSMETICS.length) return 'SKIP: this profile already owns every rack ('+base+'), so the switch has nothing to open';
       renderCheat();
       var b=document.getElementById('cheatcos');
       if(!b) return 'the cheat box has no ALL COSMETICS switch';
       if(!/OFF$/.test(b.textContent)) bad.push('the switch says "'+b.textContent+'" while the flag is off');
       b.click();
       if(!P2.cosAll) bad.push('one click did not turn the flag on');
       if(!/ON$/.test(b.textContent)) bad.push('after one click the switch says "'+b.textContent+'"');
       var on=owned();
       if(on!==COSMETICS.length) bad.push('with the switch on '+on+' of '+COSMETICS.length+' racks are owned');
       b.click();
       if(P2.cosAll) bad.push('a second click did not turn the flag off');
       if(!/OFF$/.test(b.textContent)) bad.push('after two clicks the switch says "'+b.textContent+'"');
       var off=owned();
       if(off!==base) bad.push('after cutting it off '+off+' racks are owned, not the '+base+' he had earned');
       if(JSON.stringify(P2.cosBought||{})!==keepBought) bad.push('the bought list changed');
       if(P2.runs!==keepRuns||P2.ext!==keepExt) bad.push('the earned counters changed');
     } finally {
       P2.cosAll=keepAll; try{ saveProfile(); }catch(_sv){}
       var m=document.getElementById('cheatmodal'); if(m) m.classList.remove('on');
     }
     return bad.length?bad.join('; '):null; }},
  {v:'10.52',what:'the prompt over a container is drawn as a callout and the items-left count under the search bar as a label, both on screen',
   run:function(){
     var bad=[];
     if(!(window.__startRaid&&window.__frame&&window.__textTrace&&typeof drawHUD==='function')) return 'SKIP: this build cannot trace the HUD';
     if(!(W>0&&H>0)) return 'SKIP: the pane is 0x0';
     __startRaid({seed:4242,mapIx:0});
     if(!G||!G.containers||!G.containers.length) return 'no containers on the map';
     var ct=null;
     for(var i=0;i<G.containers.length;i++){ var c=G.containers[i]; if(c&&!c.opened&&c.loot&&c.loot.length>=1&&!c.fallen&&!c.dropped){ ct=c; break; } }
     if(!ct) return 'no unopened container with loot to stand on';
     var p=G.player, keep={x:p.x,y:p.y,near:G.nearContainer,srch:G.searching,st:G.searchT,time:ct.time};
     try{
       p.x=ct.x+12; p.y=ct.y+2; p.downed=false;
       __frame(0.016);
       // Frame A: standing at the crate, not searching: the prompt.
       G.nearContainer=ct; G.searching=null; G.searchT=0;
       var trA=__textTrace(function(){ drawHUD(); });
       var pr=null;
       for(i=0;i<trA.length;i++){ if(/^\[.*\] SEARCH /.test(trA[i].t)){ pr=trA[i]; break; } }
       // Frame B: searching it: the count under the bar.
