  {v:'10.31',what:'the Blotter melts the frame on clocks rolled with the dose, so two doses never warp alike and one dose never holds still',
   run:function(){
     var bad=[];
     if(!__vpAlive()) return 'SKIP: the pane has no layout, nothing is drawn';
     if(typeof BUZZRND==='undefined') return 'the Blotter has no rolled clocks; every trip is the same score';
     __pinDPR(1); __forceSize(1920,1080); __resetCfg(); __pinDefaults(0); __cleanProfile();
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     var g=__state(); if(!g) return 'SKIP: no raid';
     var p=g.player; g.ents.length=0; p.hp=100000; p.maxhp=100000;
     var P2=__P(); var keepBuzz=P2.buzz, keepR=BUZZRND, keepT=BUZZT;
     var cvs=(window.__canvases&&__canvases().world)||document.getElementById('cv'), wctx=cvs.getContext('2d');
     function grab(t){ BUZZT=t; for(var f=0;f<2;f++) __frame(0.016); return wctx.getImageData(0,0,cvs.width,cvs.height).data; }
     function diff(a,b){ var d=0; for(var i=0;i<a.length;i+=16) if(Math.abs(a[i]-b[i])+Math.abs(a[i+1]-b[i+1])+Math.abs(a[i+2]-b[i+2])>40) d++; return d; }
     var dose=function(){ return {id:'lsd',tag:'lsd',t:150,dur:180}; };
     // No dose: the still scene, the yardstick.
     P2.buzz=[]; var c1=grab(3.0), c2=grab(3.5); var still=diff(c1,c2);
     // Two doses, one roll: the frame moves with time.
     P2.buzz=[dose(),dose()]; BUZZRND=[0.12,0.88,0.41,0.67,0.95,0.23,0.58,0.34];
     var a1=grab(3.0), a2=grab(3.5); var moved=diff(a1,a2);
     // The same moment on a different roll: a different picture.
     BUZZRND=[0.79,0.16,0.93,0.28,0.05,0.71,0.44,0.62];
     var b1=grab(3.0); var rolled=diff(a1,b1);
     // THE FINDING. On v10.30 the warp was the same score on every dose.
     if(rolled<Math.max(1500,still*3)) bad.push('two doses at the same moment differ by '+rolled+' sampled pixels against a still scene of '+still+'; the trip is the same score every time');
     if(moved<Math.max(1500,still*3)) bad.push('half a second of trip moved '+moved+' sampled pixels against a still scene of '+still);
     // A dose rolls the clocks.
     var before=BUZZRND.slice(); var _BS=(typeof BUZZ!=='undefined')?BUZZ:null; var B2=null;
     if(_BS) for(var i=0;i<_BS.length;i++) if(_BS[i].tag==='lsd') B2=_BS[i];
     if(typeof takeBuzz==='function'&&B2){ try{ takeBuzz(B2); }catch(e){} if(JSON.stringify(BUZZRND)===JSON.stringify(before)) bad.push('a fresh dose did not roll the clocks'); }
     // CONTROL: with no dose the two frames are near still.
     P2.buzz=[]; var d1=grab(3.0), d2=grab(3.5); if(diff(d1,d2)>Math.max(600,moved/4)) bad.push('control: with no dose the frame still moved '+diff(d1,d2)+' sampled pixels');
     P2.buzz=keepBuzz||[]; BUZZRND=keepR; BUZZT=keepT;
     return bad.length?bad.join('; '):null; }},
  {v:'10.30',what:'the dev cheat box stands on the floor only when a Settings switch says so, and the switch is locked until one extraction',
   run:function(){
     var bad=[];
     if(!__vpAlive()) return 'SKIP: the pane has no layout';
     if(!(window.__hubEnter&&window.__station)) return 'SKIP: this build cannot be driven into the Undercroft';
     if(typeof DEV_LOCAL==='undefined'||!DEV_LOCAL) return 'SKIP: not a local build, the box is never here';
     __pinDPR(1); __forceSize(1920,1080); __resetCfg(); __pinDefaults(0); __cleanProfile();
     var P2=__P(); var keep={ext:P2.ext,devBox:P2.devBox,primerSeen:P2.primerSeen,welcomed:P2.welcomed};
     P2.ext=0; delete P2.devBox; P2.primerSeen=1; P2.welcomed=1;
     function boxOnFloor(){ HB=null; __hubEnter(); var r=null; try{ r=__station('cheat'); }catch(e){ return false; } var cm=document.getElementById('cheatmodal'); var on=!!(r&&!r.err&&cm&&cm.classList.contains('on')); if(cm) cm.classList.remove('on'); return on; }
     // THE FINDING. On v10.29 the box stood on every local floor with no switch anywhere.
     if(boxOnFloor()) return 'a fresh character finds the dev cheat box on the floor';
     var sm=document.getElementById('settingsmodal'); sm.classList.add('on'); renderSettings();
     var b=document.getElementById('set_devbox');
     if(!b) bad.push('Settings has no row for the dev cheat box');
     else {
       if(!b.disabled||b.textContent.trim()!=='LOCKED') bad.push('with no extraction the switch reads "'+b.textContent.trim()+'" and is '+(b.disabled?'locked':'live'));
       b.click(); if(P2.devBox) bad.push('a locked switch turned the box on');
       // One extraction unlocks it.
       P2.ext=1; renderSettings(); b=document.getElementById('set_devbox');
       if(!b||b.disabled||b.textContent.trim()!=='OFF') bad.push('after one extraction the switch reads "'+(b?b.textContent.trim():'none')+'"');
       if(b){ b.click(); b=document.getElementById('set_devbox'); }
       if(!P2.devBox) bad.push('the switch did not turn the box on');
       if(b&&b.textContent.trim()!=='ON') bad.push('the switch turned on but reads "'+b.textContent.trim()+'"');
       sm.classList.remove('on');
       if(!boxOnFloor()) bad.push('with the switch on, the box is not on the floor');
       // CONTROL: off again, and it is gone again.
       sm.classList.add('on'); renderSettings(); b=document.getElementById('set_devbox'); if(b) b.click(); sm.classList.remove('on');
       if(P2.devBox) bad.push('control: the switch did not turn the box off');
       if(boxOnFloor()) bad.push('control: with the switch off the box is still on the floor');
     }
     sm.classList.remove('on');
     for(var k in keep){ if(keep[k]===undefined) delete P2[k]; else P2[k]=keep[k]; }
     HB=null;
     return bad.length?bad.join('; '):null; }},
  {v:'10.29',what:'a new character is offered the welcome pack once, a green gun, a blue gun, heals, plates and grenades into the stash',
   run:function(){
     var bad=[];
     if(!__vpAlive()) return 'SKIP: the pane has no layout';
     if(!window.__hubEnter) return 'SKIP: this build cannot be driven into the Undercroft';
     __pinDPR(1); __forceSize(1920,1080); __resetCfg(); __pinDefaults(0); __cleanProfile();
     var P2=__P(); var keep={welcomed:P2.welcomed,runs:P2.runs,stash:P2.stash,weapons:P2.weapons,primerSeen:P2.primerSeen};
     function fresh(){ P2.welcomed=undefined; delete P2.welcomed; P2.runs=0; P2.stash=[]; P2.weapons=['pistol']; P2.primerSeen=1; }
     fresh(); __hubEnter();
     var md=document.getElementById('welcomemodal');
     // THE FINDING. On v10.28 a new character landed with a pistol and nothing else, and nobody offered anything.
     if(!md) return 'there is no welcome pack window';
     if(!md.classList.contains('on')) return 'a new character is not offered the welcome pack';
     var list=(document.getElementById('welcomelist')||{}).textContent||'';
     if(!/Compact SMG/.test(list)||!/Burst Carbine/.test(list)) bad.push('the pack does not list a green gun and a blue gun ("'+list.slice(0,60)+'")');
     if(!/Medkit/.test(list)||!/Frag/.test(list)||!/Plate/.test(list)) bad.push('the pack does not list heals, plates and grenades');
     var take=document.getElementById('welcometake'); if(!take) bad.push('no TAKE button'); else take.click();
     if(md.classList.contains('on')) bad.push('taking the pack did not close the window');
     if(P2.stash.indexOf('gun_smg')<0||P2.stash.indexOf('gun_carbine')<0) bad.push('the guns did not reach the stash: '+P2.stash.join(','));   // r1329: his ruling, the pack goes to the stash
     var have={}; P2.stash.forEach(function(k){ have[k]=(have[k]||0)+1; });
     if(!(have.medkit>=2&&have.bandage>=3&&have.plate>=2&&have.frag>=2&&have.smoke>=1)) bad.push('the stash did not get the pack: '+JSON.stringify(have));
     if(gunRarity('smg')!=='uncommon'||gunRarity('carbine')!=='rare') bad.push('the guns are not one green and one blue: '+gunRarity('smg')+', '+gunRarity('carbine'));
     if(P2.welcomed!==1) bad.push('taking the pack did not stamp the profile');
     // Offered once: a second entry shows nothing.
     __hubEnter(); if(md.classList.contains('on')) bad.push('the pack was offered a second time');
     // CLOSE stamps too, and gives nothing.
     fresh(); __hubEnter();
     if(!md.classList.contains('on')) bad.push('a second fresh character was not offered the pack');
     var no=document.getElementById('welcomeno'); if(no) no.click();
     if(md.classList.contains('on')) bad.push('CLOSE did not close the window');
     if(P2.stash.length||P2.weapons.length!==1) bad.push('CLOSE gave something anyway');
     if(P2.welcomed!==1) bad.push('CLOSE did not stamp the profile');
     // CONTROL: a character who has climbed is never offered it, and is stamped quietly.
     delete P2.welcomed; P2.runs=3; P2.stash=[]; P2.weapons=['pistol']; __hubEnter();
     if(md.classList.contains('on')) bad.push('control: a character with three runs was offered the pack');
     if(P2.welcomed!==1) bad.push('control: a character with three runs was not stamped');
     md.classList.remove('on');
     for(var k in keep){ if(keep[k]===undefined) delete P2[k]; else P2[k]=keep[k]; }
     return bad.length?bad.join('; '):null; }},
  {v:'10.28',what:'the tuning console opens from a Settings row, and the Settings rows read the live dials: an option when they match one, CUSTOM when they do not',
   run:function(){
     var bad=[];
     if(!__vpAlive()) return 'SKIP: the pane has no layout';
     __pinDPR(1); __forceSize(1920,1080); __resetCfg(); __pinDefaults(0); __cleanProfile();
     var P2=__P(); var keepOpts=JSON.stringify(P2.gameOpts||{}), keepTuned=JSON.stringify(P2.tuned||{});
     P2.gameOpts={}; P2.tuned={}; try{ applyGameOpts(); }catch(e0){}
     var sm=document.getElementById('settingsmodal'); if(!sm) return 'SKIP: no Settings window';
     sm.classList.add('on'); renderSettings();
     // THE FINDING. On v10.27 Settings had no way to the console and the rows showed the last click, not the dials.
     var bt=document.getElementById('set_tune');
     if(!bt) return 'Settings has no row for the tuning console';
     var tm=document.getElementById('tunemodal');
     bt.click(); if(!(tm&&tm.classList.contains('on'))) bad.push('the OPEN button did not open the console');
     // A dial moved by hand: the row says CUSTOM, and a matching set of dials says the option.
     var row=null; for(var i=0;i<GAMEOPTS.length;i++) if(GAMEOPTS[i].k==='robots') row=GAMEOPTS[i];
     if(!row) bad.push('staging: no Machines row');
     else {
       CFG.nSentry=99; P2.tuned.nSentry=1;
       toggleTune(false);   // closing the console redraws the rows
       var b=document.getElementById('go_robots'); var t1=b?b.textContent.trim():'';
       if(t1!=='CUSTOM') bad.push('with a sentry count no option names, the Machines row reads "'+t1+'", not CUSTOM');
       var opt=row.opts[0]; for(var c in opt.cfg) CFG[c]=opt.cfg[c];
       renderSettings(); b=document.getElementById('go_robots'); var t2=b?b.textContent.trim():'';
       if(t2!==opt.n) bad.push('with the dials at the '+opt.n+' values, the row reads "'+t2+'"');
       // Clicking the row steps from what it shows, and writes the dials.
       b.click(); var nx=row.opts[1%row.opts.length];
       for(var c2 in nx.cfg) if(CFG[c2]!==nx.cfg[c2]) bad.push('after a click the dial '+c2+' is '+CFG[c2]+', not the '+nx.n+' value '+nx.cfg[c2]);
       var b3=document.getElementById('go_robots'); if(b3&&b3.textContent.trim()!==nx.n) bad.push('after a click the row reads "'+b3.textContent.trim()+'", not '+nx.n);
     }
     // CONTROL: shift and the backquote key still open it.
     toggleTune(false);
     document.dispatchEvent(new KeyboardEvent('keydown',{code:'Backquote',key:'~',shiftKey:true,bubbles:true,cancelable:true}));
     if(!(tm&&tm.classList.contains('on'))) bad.push('control: shift and the backquote key no longer open the console');
     toggleTune(false); sm.classList.remove('on');
     P2.gameOpts=JSON.parse(keepOpts); P2.tuned=JSON.parse(keepTuned); try{ applyGameOpts(); }catch(e1){} __resetCfg();
     return bad.length?bad.join('; '):null; }},
  {v:'10.27',what:'the mainframe card is NET LIFETIME EARNINGS, the sum over every run of extracted minus carried in, a death losing what it carried',
   run:function(){
     var bad=[];
     if(typeof runEarnings!=='function'||typeof netEarnFromLog!=='function') return 'the profile has no lifetime earnings; the card is still proficiency';
     __pinDPR(1); __forceSize(1920,1080); __resetCfg(); __pinDefaults(0); __cleanProfile();
     var P2=__P(); var keep={netEarn:P2.netEarn,log:P2.log,runs:P2.runs,ext:P2.ext};
     P2.netEarn=0; P2.log=[];
     // Values are read at the moment the raid values them, because a deploy can
     // move the loot multiplier and a constant read beforehand disagrees.
     // ONE: in with a medkit and a frag, out with the same: earnings zero, and the record knows both numbers.
     __deploy({kit:['medkit','frag'],safe:null,mapIx:0,seed:4242}); var g=__state(); if(!g) return 'SKIP: no raid'; g.ents.length=0;
     // The value is the BAG's, as the haul is: a frag in the kit goes to the tactical
     // belt at landing and is valued on neither side, so the bag is read as landed.
     var inV=0; for(var bi=0;bi<g.bag.length;bi++) inV+=ival(g.bag[bi]);
     if(!(inV>0)) return 'SKIP: the bag landed empty or worthless';
     if(Math.round(g.carriedIn||0)!==inV) bad.push('the lift landed with '+inV+' of kit and the raid recorded '+g.carriedIn+' carried in');
     __endRaid('extract'); var ob=document.getElementById('oc_btn'); if(ob) ob.click();
     var r1=P2.log[P2.log.length-1]||{};
     if(r1.carriedIn!==inV) bad.push('the record carries '+r1.carriedIn+' in, not '+inV);
     if(P2.netEarn!==0) bad.push('in and out with the same bag, earnings read '+P2.netEarn+', not 0');
     // TWO: die holding what landed with a plate in the kit: minus the whole landed bag.
     // (The lift adds a bandage or two of its own to any kit; the bag is read as landed.)
     __deploy({kit:['plate'],safe:null,mapIx:0,seed:4242}); g=__state(); g.ents.length=0;
     var in2=0; for(var b2=0;b2<g.bag.length;b2++) in2+=ival(g.bag[b2]);
     if(!(in2>0)) bad.push('staging: the second bag landed worthless');
     __endRaid('dead'); ob=document.getElementById('oc_btn'); if(ob) ob.click();
     if(P2.netEarn!==-in2) bad.push('dying with a bag worth '+in2+' reads '+P2.netEarn+', not '+(-in2));
     // THREE: pick up scrap and walk out with the landed bag plus the scrap: plus the scrap.
     __deploy({kit:[],safe:null,mapIx:0,seed:4242}); g=__state(); g.ents.length=0; g.bag.push('scrap'); var scrap=ival('scrap');
     __endRaid('extract'); ob=document.getElementById('oc_btn'); if(ob) ob.click();
     if(P2.netEarn!==-in2+scrap) bad.push('three runs read '+P2.netEarn+', not '+(-in2+scrap));
     var plate=in2;
     // FOUR: the card says what it is, with that number.
     var html=''; if(typeof renderStatCards==='function'){ renderStatCards(); html=(document.getElementById('statgrid')||{}).innerHTML||''; }
     if(html.indexOf('Net lifetime earnings')<0) bad.push('the card is not called Net lifetime earnings');
     if(/Net carried out/.test(html)) bad.push('the old card name is still there');
     if(html.indexOf((-plate+scrap).toLocaleString())<0) bad.push('the card does not show '+(-plate+scrap));
     if(!/extracted, minus everything you carried in/.test(html)) bad.push('the card does not explain itself');
     // FIVE: a profile from before the counter sums its log, old records counting their haul alone.
     P2.log=[{outcome:'extract',haul:500},{outcome:'dead',haul:900},{outcome:'extract',haul:300,carriedIn:120}];
     if(netEarnFromLog()!==500+300-120) bad.push('an old log sums to '+netEarnFromLog()+', not 680');
     // CONTROL: the Experience card is still beside it.
     if(html.indexOf('Experience')<0) bad.push('control: the Experience card is gone');
     for(var k in keep) P2[k]=keep[k];
     return bad.length?bad.join('; '):null; }},
  {v:'10.26',what:'the hotbar is the TACTICAL BELT everywhere a player reads it, and the old word is gone from every surface',
   run:function(){
     var bad=[];
     var OLDW=['hot','bar'].join(''), NEWW=['tactical ','belt'].join('');
     function has(t,w){ return String(t||'').toLowerCase().indexOf(w)>=0; }
     // ONE: the legends and the pause rows, read from the tables the HUD draws from.
     var tables={LEGEND:(typeof LEGEND!=='undefined')?LEGEND:null,LEGEND_PAD:(typeof LEGEND_PAD!=='undefined')?LEGEND_PAD:null,GEARRULES:(typeof GEARRULES!=='undefined')?GEARRULES:null};
     var anyNew=false;
