  {v:'10.24',what:'the Undercroft crowd dresses from every rack, eyes, beards and faces included, and the floor draws more than one eye colour',
   run:function(){
     var bad=[];
     if(!__vpAlive()) return 'SKIP: the pane has no layout';
     if(typeof hubRollLook!=='function'||typeof COSMETICS==='undefined') return 'SKIP: no crowd or no racks in this build';
     var kinds={}; COSMETICS.forEach(function(c){ kinds[c.kind]=1; });
     function valid(id,kind){ var c=cosFind(id); return !!c&&c.kind===kind; }
     var eyesSeen={}, rolled=[];
     for(var i=0;i<30;i++) rolled.push(hubRollLook());
     // THE FINDING. On v10.23 a crowd look had a skin, a hair, a hat and a cut and nothing else.
     var noEyes=rolled.filter(function(l){ return !l.eyes; }).length;
     if(noEyes) return noEyes+' of 30 crowd looks have no eyes; everyone wears the painter\'s default';
     rolled.forEach(function(l,ix){
       if(!valid(l.eyes,'eyes')) bad.push('look '+ix+' has eyes '+l.eyes+' that are not on the rack');
       if(kinds.beard&&!valid(l.beard,'beard')) bad.push('look '+ix+' has beard '+l.beard+' that is not on the rack');
       if(kinds.face&&!valid(l.faceMark,'face')) bad.push('look '+ix+' has face '+l.faceMark+' that is not on the rack');
       if(!valid(l.hair,'hair')||!valid(l.hat,'hat')||!valid(l.cut,'cut')) bad.push('look '+ix+' hair/hat/cut are not from the racks: '+l.hair+'/'+l.hat+'/'+l.cut);
       if(l.hat==='crown') bad.push('look '+ix+' wears the crown, which is his');
       eyesSeen[l.eyes]=1;
     });
     if(Object.keys(eyesSeen).length<2) bad.push('thirty crowd looks share one eye colour: '+Object.keys(eyesSeen).join(','));
     if(bad.length>6) bad.length=6;
     // On the floor: two members given blue and green eyes, and both colours drawn.
     __pinDPR(1); __forceSize(1920,1080); __resetCfg(); __pinDefaults(0); __cleanProfile();
     __hubEnter(); var hb=__hub();
     if(!hb||!hb.crowd||hb.crowd.length<2) bad.push('the floor has no crowd to dress');
     else {
       hb.crowd.forEach(function(c,ix){ if(!c.look) return; c.look.hat='none'; c.look.eyes=(ix%2)?'eyeblue':'eyegreen'; c.fade=1; });
       for(var f=0;f<20;f++) __hubFrame(0.016);
       var cv=__canvases(); var c2=cv.hub||cv.world; var d=c2.getContext('2d').getImageData(0,0,c2.width,c2.height).data;
       var blue=0, green=0, B=[74,122,184], Gc=[74,138,90];
       for(var q=0;q<d.length;q+=4){ if(d[q+3]<40) continue; if(Math.abs(d[q]-B[0])+Math.abs(d[q+1]-B[1])+Math.abs(d[q+2]-B[2])<30) blue++; if(Math.abs(d[q]-Gc[0])+Math.abs(d[q+1]-Gc[1])+Math.abs(d[q+2]-Gc[2])<30) green++; }
       if(blue<3) bad.push('blue eyes given to half the crowd draw '+blue+' blue pixels on the floor');
       if(green<3) bad.push('green eyes given to the other half draw '+green+' green pixels');
     }
     // CONTROL: the four old fields still roll, and the face index is still a number.
     var l0=hubRollLook(); if(typeof l0.faceIx!=='number'||!l0.skin) bad.push('control: the old look fields are gone');
     return bad.length?bad.join('; '):null; }},
  {v:'10.23',what:'no two station names on the Undercroft floor overlap, and every name is on the screen',
   run:function(){
     var bad=[];
     var _P0=__P(), _keepDev=_P0.devBox; _P0.devBox=1; HB=null;   // v10.30: the box is behind a switch; put it on the floor for this
     if(!__vpAlive()) return 'SKIP: the pane has no layout';
     if(!(window.__hubEnter&&window.__textTrace&&window.__hubFrame)) return 'SKIP: this build cannot trace the floor';
     __pinDPR(1); __forceSize(1920,1080); __resetCfg(); __pinDefaults(0); __cleanProfile();
     __hubEnter(); for(var f=0;f<10;f++) __hubFrame(0.016);
     var tr=__textTrace(function(){ __hubFrame(0.016); });
     // v10.93: ASK THE GAME. This list used to be typed out here, and the build
     // that renamed one station turned this check into a SKIP, which is not a
     // pass: the only guard against two names running into each other stopped
     // running on the build most likely to make them.
     var _HBn=__hub(), names=[], _lbl={};
     for(var _s=0;_s<_HBn.stations.length;_s++){ names.push(String(_HBn.stations[_s].label)); _lbl[_HBn.stations[_s].id]=String(_HBn.stations[_s].label); }
     var got={};
     for(var i=0;i<tr.length;i++){ var d=tr[i]; if(names.indexOf(String(d.t))>=0) got[d.t]={x:d.x-d.w/2,y:d.y-d.px,w:d.w,h:d.px*1.15}; }
     if(names.length<4) return 'SKIP: the Undercroft has almost no stations on it';
     if(!_lbl['mirror']||!got[_lbl['mirror']]) return 'SKIP: the racks station is not on the floor';
     if(!_lbl['cheat']||!got[_lbl['cheat']]) return 'SKIP: the cheat box is not on this floor (it shows on localhost only)';
     function hit(a,b){ return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y; }
     var keys=Object.keys(got);
     // THE FINDING. On v10.22 the racks station name ran into the cheat box's.
     for(var a=0;a<keys.length;a++) for(var b=a+1;b<keys.length;b++) if(hit(got[keys[a]],got[keys[b]])) bad.push(keys[a]+' runs into '+keys[b]);
     for(var k in got){ var r=got[k]; if(r.x<0||r.x+r.w>W||r.y<0||r.y+r.h>H) bad.push(k+' is off the screen at '+Math.round(r.x)+','+Math.round(r.y)); }
     // CONTROL: the racks station still opens from where it stands.
     var rr=null; try{ rr=__station('mirror'); }catch(e1){ rr={err:String(e1)}; }
     var md=document.getElementById('appearmodal');
     if(!rr||rr.err||!(md&&md.classList.contains('on'))) bad.push('control: the racks station did not open');
     var cl=document.getElementById('closeappear'); if(cl) cl.click();
     if(_keepDev===undefined) delete _P0.devBox; else _P0.devBox=_keepDev; HB=null;   // v10.30
     return bad.length?bad.join('; '):null; }},
  {v:'10.22',what:'the menu size never goes below 1.0, on the wheel, the Settings steps or the saved profile, and the wheel says what it did',
   run:function(){
     var bad=[];
     if(!__vpAlive()) return 'SKIP: the pane has no layout';
     if(!(window.__hubEnter&&window.__P)) return 'SKIP: this build cannot be driven into the Undercroft';
     __pinDPR(1); __forceSize(1920,1080); __resetCfg(); __pinDefaults(0); __cleanProfile();
     var P2=__P(), keepMZ=P2.menuZoom, keepUI=P2.uiScale;
     __hubEnter();
     var hub=document.getElementById('hub');
     function spin(dy){ var ev=new WheelEvent('wheel',{deltaY:dy,bubbles:true,cancelable:true,clientX:960,clientY:540}); document.body.dispatchEvent(ev); return P2.menuZoom; }
     // THE FINDING. On v10.21 the wheel took the size down to 0.7 and the saved
     // profile kept it there, and his stash at 4K was drawn at about 1.5 of 1080p.
     P2.menuZoom=1.0; applyMenuZoom();
     var down=spin(120);
     if(down<1) bad.push('the wheel took the menu size below 1.0, to '+down);
     P2.menuZoom=0.7; applyMenuZoom();
     var z=parseFloat(hub.style.zoom)||0, tr=(typeof titleRes==='function')?titleRes():1;
     if(z<tr*0.92-0.01) bad.push('a saved size of 0.7 draws the Undercroft at '+z.toFixed(2)+', below the screen factor '+(tr*0.92).toFixed(2));
     // The profile itself: loading a size below 1.0 reads as 1.0.
     // The loader is asynchronous (it reads storage and resolves later), so the floor it applies is read from its source rather than awaited.
     var _lpsrc=String(loadProfile)+((typeof applyLoadedProfile==='function')?(' '+String(applyLoadedProfile)):'');
     if(_lpsrc.indexOf(['menuZoom','<1)P.menuZoom=1'].join(''))<0) bad.push('the profile loader has no floor: a saved size below 1.0 would load as it was');
     // The Settings steps: from the smallest UI step downward the size stays at or above 1.0.
     P2.menuZoom=1.0; P2.uiScale=UISCALES[0];
     if(typeof hudSizeStep==='function'){ try{ hudSizeStep(-1); }catch(e2){} if((P2.menuZoom||0)<1) bad.push('a size step took the size to '+P2.menuZoom); }
     else bad.push('staging: no hudSizeStep to step the size with');
     // The wheel says what it did.
     P2.menuZoom=1.0; applyMenuZoom(); var t0=(typeof HUBSAY!=='undefined')?HUBSAY:null;
     var up=spin(-120);
     var tt=document.getElementById('hubtoast'); var said=(tt&&tt.textContent)||((typeof HUBSAY!=='undefined')?HUBSAY:'')||'';
     if(!/MENU SIZE\s*\d+%/.test(said)) bad.push('the wheel changed the size and said nothing ("'+String(said).slice(0,40)+'")');
     // CONTROL: upward still works, by the old notch, and the floor draws at the size asked for.
     if(Math.abs(up-1.08)>0.001) bad.push('control: the wheel up from 1.0 gave '+up+', not 1.08');
     P2.menuZoom=1.5; applyMenuZoom(); var z2=parseFloat(hub.style.zoom)||0;
     if(Math.abs(z2-1.5*tr*0.92)>0.02) bad.push('control: a size of 1.5 draws the Undercroft at '+z2.toFixed(2)+', not '+(1.5*tr*0.92).toFixed(2));
     P2.menuZoom=keepMZ||1.3; P2.uiScale=keepUI; try{ saveProfile(); }catch(e3){} applyMenuZoom();
     return bad.length?bad.join('; '):null; }},
