     var cons=[].filter.call(hub.querySelectorAll('#stashtabs .invtab'),function(d){ return (/^CONSUMABLES/).test(d.textContent.trim()); })[0];
     if(!cons) bad.push('no CONSUMABLES tab to click');
     else {
       cons.click();
       // a stash cell carries the item's name in its title
       var titles=[].map.call(hub.querySelectorAll('#stashgrid .cell'),function(c){ return String(c.title||''); }).join(' | ');
       var plateName=(ITEMS.plate||{}).name||'Armour Plate', medName=(ITEMS.medkit||{}).name||'Medkit';
       if(titles.indexOf(plateName)<0) bad.push('the CONSUMABLES tab does not show the armour plate: ['+titles.slice(0,120)+']');
       if(titles.indexOf(medName)<0) bad.push('the CONSUMABLES tab does not show the medkit');
     }
     // OTHER shows only when something falls into it: with this stash, nothing.
     if(tabs.indexOf('OTHER')>=0) bad.push('an OTHER tab is drawn with nothing in it');
     // CONTROL: the ALL count is the whole stash.
     var all=[].filter.call(hub.querySelectorAll('#stashtabs .invtab'),function(d){ return (/^ALL/).test(d.textContent.trim()); })[0];
     var m=all?/(\d+)\s*$/.exec(all.textContent.trim()):null;
     var wantAll=P2.stash.length+((P2.weapons||[]).length);   // ALL counts the guns you own too, its rule since the tabs were built
     if(!m||+m[1]!==wantAll) bad.push('control: ALL counts '+(m?m[1]:'nothing')+' against a stash of '+P2.stash.length+' plus '+((P2.weapons||[]).length)+' owned guns');
     P2.stashTab='all'; hub.classList.remove('on');
     return bad.length?bad.join('; '):null; }},
  {v:'10.10',what:'every window has a CLOSE and ESC closes the window in front',
   run:function(){
     var bad=[];
     if(!__vpAlive()) return 'SKIP: the pane has no layout';
     if(!window.__hubEnter) return 'SKIP: this build cannot be driven into the Undercroft';
     __pinDPR(1); __forceSize(1920,1080); __resetCfg(); __pinDefaults(0); __cleanProfile();
     __hubEnter();
     // ONE: every modal has a way out that says CLOSE (the loadout question's is NO).
     var ms=document.querySelectorAll('.modal'), noClose=[], wrongWord=[];
     for(var i=0;i<ms.length;i++){
       var m=ms[i], id=m.id||('modal'+i);
       if(id==='askmodal'){ if(!m.querySelector('#askno')) noClose.push(id); continue; }
       var bs=m.querySelectorAll('button'), found=null;
       for(var b=0;b<bs.length;b++){ var t=bs[b].textContent.trim(); if(/^(CLOSE|Close|Leave|Back|Done)$/i.test(t)){ found=t; break; } }
       if(!found) noClose.push(id);
       else if(found!=='CLOSE') wrongWord.push(id+' says '+found);
     }
     if(noClose.length) bad.push('windows with no way out: '+noClose.join(', '));
     if(wrongWord.length) bad.push('windows whose way out is not CLOSE: '+wrongWord.join(', '));
     // TWO: ESC over an open window closes it. Open a few through the game's
     // own openers and press ESC through the real handler.
     function esc(){ document.dispatchEvent(new KeyboardEvent('keydown',{code:'Escape',key:'Escape',bubbles:true,cancelable:true})); }
     var opened=[], stuck=[];
     var tries=[['gamblemodal',function(){ if(typeof renderGamble==='function') renderGamble(); openModal('gamblemodal'); }],
                ['barmodal',function(){ if(typeof renderBar==='function') renderBar(); openModal('barmodal'); }],
                ['sectormodal',function(){ if(typeof renderSector==='function') renderSector(); openModal('sectormodal'); }],
                ['cheatmodal',function(){ if(typeof renderCheat==='function') renderCheat(); openModal('cheatmodal'); }],
                ];
     for(var t2=0;t2<tries.length;t2++){
       var mid=tries[t2][0], el=document.getElementById(mid); if(!el) continue;
       try{ tries[t2][1](); }catch(e1){ continue; }
       if(!el.classList.contains('on')) continue;
       opened.push(mid);
       esc();
       if(el.classList.contains('on')){ stuck.push(mid); el.classList.remove('on'); }
     }
     if(!opened.length) return bad.length?bad.join('; '):'SKIP: no window would open to test ESC on';
     if(stuck.length) bad.push('ESC did not close: '+stuck.join(', '));
     // CONTROL: ESC with nothing open still does what it did, and the stash
     // screen still closes on ESC.
     var hub=document.getElementById('hub');
     if(hub){ hub.classList.add('on'); esc(); if(hub.classList.contains('on')){ bad.push('control: ESC no longer closes the stash screen'); hub.classList.remove('on'); } }
     var pb=document.getElementById('pausebox'); if(pb) pb.classList.remove('on');
     return bad.length?bad.join('; '):null; }},
  {v:'10.09',what:'gun icons are told apart by family, outlined, and every one draws',
   run:function(){
     var bad=[];
     if(typeof gunIcon!=='function'||typeof WEAPONS==='undefined') return 'SKIP: no gun painter in this build';
     var S=26, ids=[];
     for(var k in WEAPONS) if(WEAPONS.hasOwnProperty(k)&&k!=='fists') ids.push(k);
     function paint(id){
       var cv2=document.createElement('canvas'); cv2.width=S; cv2.height=S;
       var c2=cv2.getContext('2d');
       try{ gunIcon(c2,id,S/2,S/2,S*0.82); }catch(e){ return null; }
       return c2.getImageData(0,0,S,S).data;
     }
     var px={}, drawn={}, ink={};
     for(var i=0;i<ids.length;i++){
       var d=paint(ids[i]); if(!d){ bad.push('painting '+ids[i]+' threw'); continue; }
       px[ids[i]]=d; var on=0, dark=0;
       for(var q=0;q<d.length;q+=4){ if(d[q+3]>40){ on++; if(d[q]+d[q+1]+d[q+2]<90) dark++; } }
       drawn[ids[i]]=on; ink[ids[i]]=dark;
       if(on<40) bad.push(ids[i]+' draws only '+on+' pixels at 26');
     }
     // THE FINDING, part one: a dark outline. On v10.08 the icons were flat
     // rarity colour on a soft shadow, no edge, so they melted into the cell.
     var noEdge=[];
     for(var e=0;e<ids.length;e++) if(px[ids[e]]&&ink[ids[e]]<15) noEdge.push(ids[e]+' ('+ink[ids[e]]+')');
     if(noEdge.length) bad.push('icons with no dark outline: '+noEdge.join(', '));
     // Part two: different families look different. Pairs across families
     // must differ in at least a fifth of the pixels either draws.
     var FAM=(typeof GUN_FAMILY!=='undefined')?GUN_FAMILY:null;
     var same=[];
     for(var a=0;a<ids.length;a++) for(var b=a+1;b<ids.length;b++){
       var A=px[ids[a]], B=px[ids[b]]; if(!A||!B) continue;
       var fa=FAM?FAM[ids[a]]:null, fb=FAM?FAM[ids[b]]:null;
       if(FAM&&fa===fb) continue;
       var diff=0; for(var t=0;t<A.length;t+=4){ var oa=A[t+3]>40, ob=B[t+3]>40; if(oa!==ob||(oa&&Math.abs(A[t]-B[t])+Math.abs(A[t+1]-B[t+1])+Math.abs(A[t+2]-B[t+2])>60)) diff++; }
       var need=Math.max(20,Math.round(Math.max(drawn[ids[a]],drawn[ids[b]])*0.2));
       if(diff<need) same.push(ids[a]+' vs '+ids[b]+' ('+diff+' px)');
     }
     if(same.length) bad.push('guns that look the same: '+same.slice(0,8).join(', ')+(same.length>8?(' and '+(same.length-8)+' more'):''));
     // CONTROL: the icon cache still serves these, so the hotbar and the stash
     // get the new faces and not a stale data URL.
     if(typeof itemIconURL==='function'){
       var u=itemIconURL('gun_pistol',S);
       if(!/^data:image/.test(String(u))) bad.push('control: the icon cache did not return an image for the pistol');
     }
     return bad.length?bad.join('; '):null; }},
  {v:'10.08',what:'the Organ is the Pillbox on every surface that names it',
