           if(d.y<GB.y-2||d.y>GB.y+GB.h+2) outside.push(String(d.t).slice(0,16)+' @y'+Math.round(d.y));
         }
         if(outside.length) bad.push('control: gear text outside the gear box at '+W+'x'+H+': '+outside.slice(0,4).join(', '));
       }
     }
     __pinDPR(1); __forceSize(1920,1080);
     if(!sawGear) bad.push('control: no gear box was reported at all');
     return bad.length?bad.join('; '):null; }},
  {v:'10.00',what:'every headgear in the wardrobe is drawn on the operator, and every hair and clothing colour has a swatch',
   run:function(){
     var bad=[];
     if(!__vpAlive()) return 'SKIP: the pane has no layout, nothing is drawn';
     if(typeof COSMETICS==='undefined'||typeof cosSwatch!=='function') return 'SKIP: no wardrobe in this build';
     __pinDPR(1); __forceSize(1920,1080); __resetCfg(); __pinDefaults(0); __cleanProfile();
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     var g=__state(); if(!g) return 'SKIP: no raid';
     var p=g.player; g.ents.length=0; p.hp=100000; p.maxhp=100000;
     var P2=__P(); var keepHat=P2.cosHat;
     // EARN EVERYTHING FIRST. cosWorn refuses a locked hat and draws Bare
     // instead, so an unearned crown or hood would read as "draws nothing".
     var keep={runs:P2.runs,ext:P2.ext,kills:P2.kills,spClaimed:P2.spClaimed,xpLevel:P2.xpLevel};
     P2.runs=999; P2.ext=999; P2.kills={warden:9}; P2.xpLevel=99;
     P2.spClaimed=[]; for(var sc=0;sc<((typeof SEASON_TIERS!=='undefined')?SEASON_TIERS.length:0);sc++) P2.spClaimed.push(sc);
     function unearn(){ P2.runs=keep.runs; P2.ext=keep.ext; P2.kills=keep.kills; P2.spClaimed=keep.spClaimed; P2.xpLevel=keep.xpLevel; }
     // The head of the operator sprite, read off the world canvas after a real
     // frame. Each headgear must change those pixels against Bare; on v9.99
     // the four new ids fell through every branch and drew nothing.
     var cvs=(window.__canvases&&__canvases().world)||document.getElementById('cv');
     var wctx=cvs.getContext('2d');
     function headPixels(){
       for(var f=0;f<3;f++) __frame(0.016);
       // Where he actually draws: his world position less the camera, which
       // leads him. Measured at 1026,900 on a 1920x1080 frame, head at 865.
       var sx=Math.round(p.x-(g.camX||0)), sy=Math.round(p.y-(g.camY||0));
       sx=Math.max(40,Math.min(cvs.width-40,sx)); sy=Math.max(90,Math.min(cvs.height-20,sy));
       return wctx.getImageData(sx-40,sy-90,80,110).data;
     }
     function diff(a,b){ var d=0; for(var i=0;i<a.length;i+=4) if(Math.abs(a[i]-b[i])+Math.abs(a[i+1]-b[i+1])+Math.abs(a[i+2]-b[i+2])>40) d++; return d; }
     P2.cosHat='none'; var bare=headPixels();
     var hats=COSMETICS.filter(function(c){ return c.kind==='hat'&&c.id!=='none'; }), flat=[], drawn=0;
     for(var i=0;i<hats.length;i++){
       P2.cosHat=hats[i].id;
       var px=headPixels(), d=diff(px,bare);
       if(d<6) flat.push(hats[i].id+' ('+d+' px)'); else drawn++;
     }
     P2.cosHat=keepHat; unearn();
     if(!drawn) return 'SKIP: no headgear changed the sprite at all, so the hero is not where this check looks';
     if(flat.length) bad.push('headgear that draws nothing on the operator: '+flat.join(', '));
     // Every hair and clothing colour has a colour in its table, so the swatch
     // and the sprite have something to paint.
     var noCol=[];
     COSMETICS.forEach(function(c){
       if(c.kind==='hair'&&!HAIRCOL[c.id]) noCol.push('hair '+c.id);
       if(c.kind==='fit'&&!FITCOL[c.id]) noCol.push('clothing '+c.id);
       if(c.kind==='skin'&&!SKINCOL[c.id]) noCol.push('skin '+c.id);
     });
     if(noCol.length) bad.push('wardrobe entries with no colour to paint: '+noCol.join(', '));
     // And the other way: a colour in the table that the wardrobe never offers
     // is a thing nobody can wear. On v9.99 that was ash and violet hair.
     var orphan=[];
     for(var hk in HAIRCOL) if(HAIRCOL.hasOwnProperty(hk)&&!COSMETICS.some(function(c){ return c.kind==='hair'&&c.id===hk; })) orphan.push('hair '+hk);
     for(var fk in FITCOL) if(FITCOL.hasOwnProperty(fk)&&!COSMETICS.some(function(c){ return c.kind==='fit'&&c.id===fk; })) orphan.push('clothing '+fk);
     if(orphan.length) bad.push('colours nobody can wear: '+orphan.join(', '));
     // Every headgear has a swatch that is not the question mark, and a figure glyph.
     var qm=[];
     hats.forEach(function(c){ if(/>\?</.test(cosSwatch(c))) qm.push(c.id); });
     if(qm.length) bad.push('headgear with no swatch, drawn as a question mark: '+qm.join(', '));
     // CONTROL: the wardrobe grew. Fewer than nine headgear or seven hair
     // colours means this build did not add what it says it added.
     if(hats.length<9) bad.push('control: only '+hats.length+' headgear besides Bare');
     if(COSMETICS.filter(function(c){ return c.kind==='hair'; }).length<7) bad.push('control: fewer than seven hair colours');
     return bad.length?bad.join('; '):null; }},
  {v:'9.99',what:'Appearance is a station of its own, opening a screen with the figure and the whole wardrobe',
   run:function(){
     var bad=[];
     if(!__vpAlive()) return 'SKIP: the pane has no layout';
     if(!(window.__hubEnter&&window.__station)) return 'SKIP: this build cannot be driven into the Undercroft';
     __pinDPR(1); __forceSize(1920,1080); __resetCfg(); __pinDefaults(0); __cleanProfile();
     var P2=__P();
     __hubEnter();
     // ONE: the station exists and opens its own screen.
     var r=null; try{ r=__station('mirror'); }catch(e1){ r={err:String(e1)}; }
     if(!r||r.err) return 'there is no Appearance station on the floor: '+(r&&r.err);
     var md=document.getElementById('appearmodal');
     if(!(md&&md.classList.contains('on'))) return 'the Appearance station opened nothing';
     function vis(el){ if(!el) return false; var q=el.getBoundingClientRect(); return q.width>0&&q.height>0; }
     // TWO: the figure with its six slots, and the wardrobe with every group
     // showing before anything is clicked.
     var slots=md.querySelectorAll('#appavatar .avslot');
     if(slots.length<6) bad.push('the figure has '+slots.length+' slots, fewer than six');
     var tiles=md.querySelectorAll('#appavatarpicker .costile');
     if(!tiles.length) bad.push('the wardrobe is empty before a slot is clicked');
     var groups=['BUILD','SKIN','HAIR','HAIRSTYLE','HEADGEAR','CLOTHING'], missing=[];
     var wt=(document.getElementById('appavatarpicker')||{}).textContent||'';
     for(var g=0;g<groups.length;g++) if(wt.indexOf(groups[g])<0) missing.push(groups[g]);
     if(missing.length) bad.push('the wardrobe does not show '+missing.join(', '));
     if(md.querySelector('[data-save],[data-load]')) bad.push('the loadout saves are on the Appearance screen, where they do not belong');
     // THREE: a tile changes what he wears. Pick an owned, unworn tile.
     var pick=null;
     for(var i=0;i<tiles.length;i++){ var t=tiles[i]; if(!/\block\b/.test(t.className)&&!/\bon\b/.test(t.className)){ pick=t; break; } }
     if(!pick) bad.push('no owned, unworn tile to try');
     else {
       var kind=pick.getAttribute('data-kind'), id=pick.getAttribute('data-id');
       var key=(typeof COSKEY!=='undefined'&&COSKEY[kind])?COSKEY[kind]:null;
       var before=key?P2[key]:null;
       pick.click();
       if(!key) bad.push('cannot read the profile key for '+kind);
       else if(P2[key]!==id) bad.push('clicking the '+kind+' tile '+id+' left him wearing '+P2[key]+' (was '+before+')');
     }
     // FOUR: it closes.
     var cl=document.getElementById('closeappear');
     if(!vis(cl)) bad.push('there is no Leave on the Appearance screen');
     else { cl.click(); if(md.classList.contains('on')) bad.push('Leave did not close the Appearance screen'); }
     md.classList.remove('on');
     return bad.length?bad.join('; '):null; }},
  {v:'9.98',what:'the stash screen is four things: stash, backpack, hotbar, freebie kit, with one way out (the safe pocket was the fifth until v12.35 deleted it)',
   run:function(){
     var bad=[];
     if(!__vpAlive()) return 'SKIP: the pane has no layout';
     if(!(window.__hubEnter&&window.__station)) return 'SKIP: this build cannot be driven into the Undercroft';
     __pinDPR(1); __forceSize(1920,1080); __resetCfg(); __pinDefaults(0); __cleanProfile();
     var P2=__P(); P2.stash=['frag','frag','plate']; P2.kit=['frag']; P2.hotAssign={};
     __hubEnter();
     var hub=document.getElementById('hub');
     if(!hub) return 'SKIP: no stash screen in the page';
     try{ __station('term'); }catch(e1){ return 'the stash terminal threw: '+e1; }
     if(!hub.classList.contains('on')) return 'the stash terminal did not open the stash screen';
     function vis(el){ if(!el) return false; var r=el.getBoundingClientRect(); return r.width>0&&r.height>0; }
     // ONE: what he struck out is gone from this screen.
     var gone=['avpanel','avatar','avpicker','readyline','backfloor','shopbtn','workbtn','opbtn','condbtn','laybtn','optbtn'];
     var still=[];
     for(var i=0;i<gone.length;i++){ var g=hub.querySelector('#'+gone[i]); if(g&&vis(g)) still.push(gone[i]); }
     if(still.length) bad.push('still on the stash screen: '+still.join(', '));
     if(hub.querySelector('[data-save],[data-load]')) bad.push('the loadout save rows are still on the stash screen');
     if(/YOUR OPERATOR/i.test(hub.textContent)) bad.push('the stash screen still says YOUR OPERATOR');
     if(/ascend with/i.test(hub.textContent)) bad.push('the armour line is still on the stash screen');
     // TWO: his five parts are there and drawn.
     var need={stash:'#stashgrid',backpack:'#kitgrid',hotbar:'#hotplanwrap',freebie:'#hubfreekit .fkbtn'};
     for(var k in need){ var el=hub.querySelector(need[k]); if(!vis(el)) bad.push('the '+k+' part is missing or not drawn'); }
     var cells=hub.querySelectorAll('[data-plan]');
     if(cells.length!==9) bad.push('the hotbar has '+cells.length+' cells, not nine');
     // THREE: one way out with the mouse, and it works.
     var cl=hub.querySelector('#stashclose');
     if(!vis(cl)) bad.push('there is no CLOSE on the stash screen');
     else { cl.click(); if(hub.classList.contains('on')) bad.push('CLOSE did not close the stash screen'); }
     // CONTROL: the ascent check still has its operator panel, so cosmetics are
     // not lost before Appearance exists.
     var st=document.getElementById('stagemodal');
     if(st){
       var sp=document.getElementById('stageplan'), spWas=sp?sp.innerHTML:null;
       try{ if(window.__renderStage) __renderStage(); }catch(e2){}
       if(!document.getElementById('stageavatar')) bad.push('control: the ascent check lost its operator panel too');
       st.classList.remove('on');
       // Leave the ascent check as found: its hotbar cells come first in the
       // document and a later check that asks for cell 5 would get them.
       if(sp&&spWas!==null) sp.innerHTML=spWas;
     }
     hub.classList.remove('on');
     return bad.length?bad.join('; '):null; }},
  {v:'9.97',what:'day or night is chosen on the sector page, and the lift opens that page every time',
   run:function(){
     var bad=[];
     if(!__vpAlive()) return 'SKIP: the pane has no layout';
     if(!(window.__hubEnter&&window.__station)) return 'SKIP: this build cannot be driven into the Undercroft';
     __pinDPR(1); __forceSize(1920,1080); __resetCfg(); __pinDefaults(0); __cleanProfile();
     var P2=__P(); var keepCond=P2.cond; P2.cond='day';
     __hubEnter();
     var sm=document.getElementById('sectormodal'), ask=document.getElementById('askmodal');
     function shut(){ if(sm) sm.classList.remove('on'); if(ask) ask.classList.remove('on'); var st=document.getElementById('stagemodal'); if(st) st.classList.remove('on'); }
     function done(v){ shut(); P2.cond=keepCond; return v; }
     shut();
     // ONE: the lift opens the sector page, whatever the map count.
     try{ __station('lift'); }catch(e1){ return done('the lift threw: '+e1); }
     if(!(sm&&sm.classList.contains('on'))){
       bad.push('taking the lift did not open the sector page'+((ask&&ask.classList.contains('on'))?', it went straight to the loadout question':''));
       return done(bad.join('; '));
     }
     // TWO: the choice is on it, and it works both ways.
     var d=document.getElementById('condday'), nt=document.getElementById('condnight');
