     if(!/^DAY$/.test(d.textContent.trim())||!/^NIGHT$/.test(nt.textContent.trim())) bad.push('the buttons read ['+d.textContent.trim()+'] and ['+nt.textContent.trim()+']');
     nt.click();
     if(P2.cond!=='night') bad.push('clicking NIGHT left the surface at '+P2.cond);
