     var nc=getComputedStyle(nt).borderColor, dc=getComputedStyle(d).borderColor;
     if(nc===dc) bad.push('after NIGHT the two buttons look the same, so the choice is not shown');
     d.click();
     if(P2.cond!=='day') bad.push('clicking DAY left the surface at '+P2.cond);
     // THREE: the old stash button, while it still exists, stays in step.
     var cb=document.getElementById('condbtn');
     if(cb){ nt.click(); if(!/NIGHT/.test(cb.textContent)) bad.push('the stash button did not follow the sector page to NIGHT'); d.click(); }
     // CONTROL: the sector page still leads to the loadout question.
     var dep=document.getElementById('sectordeploy');
     if(dep){ dep.click(); if(!(ask&&ask.classList.contains('on'))&&!document.getElementById('stagemodal').classList.contains('on')) bad.push('control: ASCEND on the sector page no longer leads to the loadout question'); }
     return done(bad.length?bad.join('; '):null); }},
  {v:'9.96',what:'a dose from the bar pays 2.5 percent more raid XP per dose while it lasts, and nothing on a sale',
   run:function(){
     var bad=[];
     if(typeof addProgress!=='function'||typeof spForRun!=='function'||typeof xpForRun!=='function') return 'SKIP: no progress functions in this build';
     __resetCfg(); __pinDefaults(0); __cleanProfile();
     var P2=__P();
     var rec={outcome:'extract',containers:6,dist:3000,haul:1200,kills:{}};
     function runPays(doses){
       P2.buzz=[]; for(var i=0;i<doses;i++) P2.buzz.push({id:(i%2?'lsd':'liquor'),tag:(i%2?'lsd':'drunk'),t:120,dur:180});
       P2.xp=1000; P2.profRaw=0;
       var r2={}; for(var k in rec) r2[k]=rec[k];
       addProgress(r2);
       return (P2.xp||0)-1000;
     }
     var base=spForRun(rec)+xpForRun(rec);
     if(!(base>0)) return 'SKIP: the run record is worth nothing, so nothing can be multiplied';
     var sober=runPays(0), two=runPays(2), ten=runPays(10), twelve=runPays(12);
     // THE FINDING. On v9.95 a run paid the same with two doses in his blood as sober.
     if(sober!==base) bad.push('sober, the run paid '+sober+' against the '+base+' the rules add up to');
     if(two<=sober) bad.push('with two doses in his blood the run paid '+two+', the same as sober');
     else {
       var want2=Math.round(base*1.05);
       if(Math.abs(two-want2)>1) bad.push('two doses paid '+two+', not the '+want2+' that two and a half percent a dose gives');
       var want10=Math.round(base*1.25);
       if(Math.abs(ten-want10)>1) bad.push('ten doses paid '+ten+', not '+want10);
       if(twelve!==ten) bad.push('twelve doses paid '+twelve+' against ten paying '+ten+', so the bonus does not stop at ten');
     }
     // CONTROL: the dial at zero is the old game.
     __cfg({buzzXp:0});
     var off=runPays(2);
     if(off!==sober) bad.push('control: with the dial at 0 two doses still paid '+off+' against '+sober);
     __cfg({buzzXp:0.025});
     // A SALE pays NO bonus, his answer 42. Sell all, one loose piece, two doses.
     P2.buzz=[{id:'liquor',tag:'drunk',t:120,dur:180},{id:'liquor',tag:'drunk',t:120,dur:180}];
     // Whatever the button's own rule will sell: loose salvage with no use and
     // not a crafting part. Scrap is a part and the button refuses it on purpose.
     var pick=null;
     if(typeof sellable==='function'&&typeof ival==='function')
       for(var pk in ITEMS) if(ITEMS.hasOwnProperty(pk)&&sellable(pk)&&ival(pk)>0){ pick=pk; break; }
     P2.stash=pick?[pick]:[]; P2.kit=[]; P2.hotAssign={}; P2.junk=[]; P2.xp=1000; P2.credits=0;
     var sb=document.getElementById('sellall');
     if(sb&&pick){
       var v=ival(pick);
       try{ sb.onclick(); }catch(e1){ bad.push('sell all threw: '+e1); }
       var got=(P2.xp||0)-1000;
       if(P2.credits!==v) bad.push('sell all paid $'+P2.credits+' for '+pick+' worth $'+v+', so this probe did not sell what it staged');
       else if(got!==v) bad.push('selling '+pick+' worth '+v+' with two doses paid '+got+' XP, not its plain '+v+'; sales take no bar bonus');
     } else bad.push('no sell-all button to drive, or nothing the button would sell');
     // The bar says so. Two doses of liquor: IN YOUR BLOOD x2, and the bonus.
     // v12.98: the bonus counts both drinks together, so it is printed once on the
     // bar line rather than as a share on each row; with two doses of one kind the
     // figure is the same either way, which is why this arm still reads 5%.
     if(typeof renderBar==='function'){
       try{ renderBar(); }catch(e2){}
       // v13.01 moved the live total into its own element, so a number can never take
       // his edited sentence off the line he wrote. All three are what he sees.
       var bl=document.getElementById('barlist'), bln=document.getElementById('bar_line'),
           bnw=document.getElementById('bar_now');
       var bt=((bl&&bl.textContent)||'')+' '+((bln&&bln.textContent)||'')+' '+((bnw&&bnw.textContent)||'');
       if(bt.indexOf('XP +5%')<0) bad.push('the bar does not say XP +5% beside two doses of liquor');
     }
     P2.buzz=[];
     return bad.length?bad.join('; '):null; }},
  {v:'9.95',what:'in a raid the wheel zooms and ctrl-wheel sizes the HUD; inside a scrolling menu the wheel scrolls',
   run:function(){
     var bad=[];
     if(!__vpAlive()) return 'SKIP: the pane has no layout, no wheel can be aimed';
     if(typeof UISCALES==='undefined'||typeof uiScale!=='function'||typeof zoomTarget!=='function') return 'SKIP: this build has no HUD size steps';
     function wheel(el,dy,ctrl){
       var ev=new WheelEvent('wheel',{deltaY:dy,deltaMode:0,bubbles:true,cancelable:true,ctrlKey:!!ctrl});
       el.dispatchEvent(ev); return ev;
     }
     function idxOf(v){ for(var i=0;i<UISCALES.length;i++) if(Math.abs(UISCALES[i]-v)<0.001) return i; return -1; }
     __pinDPR(1); __forceSize(1920,1080); __resetCfg(); __pinDefaults(0); __cleanProfile();
     var P2=__P(); var keepScale=P2.uiScale, keepMZ=P2.menuZoom;
     // Start from the middle of the table so a step either way is possible.
     P2.uiScale=UISCALES[Math.floor(UISCALES.length/2)]; P2.menuZoom=1;
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     var g=__state(); if(!g) return 'SKIP: no raid';
     function done(v){ P2.uiScale=keepScale; P2.menuZoom=keepMZ; try{ applyMenuZoom(); }catch(_e){} return v; }
     // ONE: ctrl-wheel up in a raid is one HUD step up, and the world does not zoom.
     var i0=idxOf(uiScale()), z0=zoomTarget();
     wheel(cv,-100,true);
     var i1=idxOf(uiScale()), z1=zoomTarget();
     if(i1!==i0+1) bad.push('ctrl-wheel up moved the HUD size from step '+i0+' to '+i1+', not one step up');
     if(Math.abs(z1-z0)>1e-6) bad.push('ctrl-wheel also zoomed the world, '+z0.toFixed(3)+' to '+z1.toFixed(3));
     // and one step back down.
     wheel(cv,100,true);
     if(idxOf(uiScale())!==i0) bad.push('ctrl-wheel down did not step the HUD back');
     // CONTROL: the plain wheel still zooms and leaves the HUD alone.
     var zb=zoomTarget(), ib=idxOf(uiScale());
     wheel(cv,-100,false);
     if(!(zoomTarget()>zb)) bad.push('control: the plain wheel no longer zooms in');
     if(idxOf(uiScale())!==ib) bad.push('control: the plain wheel changed the HUD size');
     // TWO: the Undercroft. Wirt's list made scrollable, the wheel over it must
     // scroll, not size the menus. The floor beside it must still size them.
     var shut=['stagemodal','sectormodal','outcome','title','pausebox'], was={};
     for(var si=0;si<shut.length;si++){ var se=document.getElementById(shut[si]); was[shut[si]]=!!(se&&se.classList.contains('on')); if(se) se.classList.remove('on'); }
     var hub=document.getElementById('hub'), hubWas=!!(hub&&hub.classList.contains('on'));
     function restore(v){
       for(var q=0;q<shut.length;q++){ var e2=document.getElementById(shut[q]); if(!e2) continue; if(was[shut[q]]) e2.classList.add('on'); else e2.classList.remove('on'); }
       if(hub){ if(hubWas) hub.classList.add('on'); else hub.classList.remove('on'); }
       var gm2=document.getElementById('gamblemodal'); if(gm2) gm2.classList.remove('on');
       return done(v);
     }
     __showScreen('hub'); if(hub) hub.classList.add('on');
     var gm=document.getElementById('gamblemodal'), list=document.getElementById('gamblelist');
     if(!gm||!list||typeof renderGamble!=='function') return restore(bad.length?bad.join('; '):'SKIP: no Wirt list to scroll');
     P2.credits=50000; P2.gambleLog=[]; for(var k=0;k<40;k++) P2.gambleLog.push('scrap');
     gm.classList.add('on');
     try{ renderGamble(); }catch(e1){ return restore('renderGamble threw: '+e1); }
     if(!(list.scrollHeight-list.clientHeight>2)) return restore(bad.length?bad.join('; '):'SKIP: the list did not overflow, so there is nothing to scroll');
     var row=list.firstElementChild||list;
     var mz0=(__P().menuZoom||1);
     var ev1=wheel(row,100,false);
     var mz1=(__P().menuZoom||1);
     if(Math.abs(mz1-mz0)>1e-6) bad.push('the wheel over the scrolling list resized the menus, '+mz0+' to '+mz1);
     if(ev1.defaultPrevented) bad.push('the wheel over the scrolling list was swallowed, so it cannot scroll');
     // CONTROL: on the floor, with no scrollable box under the pointer, the wheel
     // still sizes the menus.
     gm.classList.remove('on');
     var floor=document.getElementById('hub')||document.body;
     var mz2=(__P().menuZoom||1);
     wheel(floor,-100,false);   // v10.22: upward, because the size floors at 1.0 and this check starts there
     var mz3=(__P().menuZoom||1);
     if(Math.abs(mz3-mz2)<1e-6) bad.push('control: the wheel on the Undercroft floor no longer sizes the menus');
     return restore(bad.length?bad.join('; '):null); }},
  {v:'9.94',what:'Wirt has two counters, per roll and a five minute Limited Time Offer that names its item',
   run:function(){
     var bad=[];
     if(!__vpAlive()) return 'SKIP: the pane has no layout, nothing is measured';
     if(typeof renderGamble!=='function'||typeof wirtLotKey!=='function') return 'SKIP: no Wirt in this build';
     // Needles from halves: this page embeds the source it tests.
     var AGO=[' a',' go'].join(''), CARRY=['carry it ','out of here'].join(''), HOUR=['for the ','hour'].join('');
     __pinDPR(1); __forceSize(1920,1080); __cleanProfile();
     var P2=__P(); P2.credits=50000; P2.gambleLog=[]; P2.stash=[];
     var gm=document.getElementById('gamblemodal'); if(!gm) return 'SKIP: no Wirt panel in the page';
     var wasOn=gm.classList.contains('on'); gm.classList.add('on');
     try{ renderGamble(); }catch(e0){ gm.classList.toggle('on',wasOn); return 'renderGamble threw: '+e0; }
     var txt=gm.textContent||'';
     // ONE: the two strings he named.
     if(txt.indexOf('$2,500 per roll')<0&&txt.indexOf('$2500 per roll')<0) bad.push('the wallet line does not say $2,500 per roll');
     if(new RegExp('\\$2,?500'+AGO+'\\b').test(txt)) bad.push('the screen still says $2,500'+AGO);
     if(txt.indexOf(CARRY)>=0) bad.push('the sentence about not having to '+CARRY+' is still there');
     // TWO: the offer card says three things and nothing else.
     var lot=document.getElementById('wirtlot');
     if(!lot) bad.push('no offer card');
     else {
       var lines=[].map.call(lot.querySelectorAll('span[style*="display:block"],span[style*="display: block"]'),function(s){ return s.textContent.trim(); });
       // v10.03, his answer 38: four lines, the item's name second.
       if(lines.length!==4) bad.push('the offer card has '+lines.length+' lines, ['+lines.join(' | ')+'], not four');
       else {
         if(lines[0]!=='Limited Time Offer') bad.push('line one reads ['+lines[0]+']');
         var headName=(ITEMS[(wirtLotKey()||[])[0]]||{}).name||'';
         if(!headName||lines[1].indexOf(headName)<0) bad.push('line two does not name the item '+headName+', it reads ['+lines[1]+']');
         if(!/^Worth \$[\d,]+$/.test(lines[2])) bad.push('line three reads ['+lines[2]+']');
         if(!/^New item in \d+ minutes?$/.test(lines[3])) bad.push('line four reads ['+lines[3]+']');
         var m=/New item in (\d+)/.exec(lines[3]); if(m&&+m[1]>5) bad.push('the card promises a new item in '+m[1]+' minutes, more than five');
       }
       if((lot.textContent||'').indexOf(HOUR)>=0) bad.push('the card still says on the counter '+HOUR);
     }
     // THREE: the delineation, measured. Two boxes, one headed THE GAMBLE and
     // one LIMITED TIME OFFER, each with its own border, and clear air between.
     var sg=document.getElementById('wirtsec_gamble'), so=document.getElementById('wirtsec_offer');
     if(!sg||!so) bad.push('the two sections are not there as their own boxes');
     else {
       var rg=sg.getBoundingClientRect(), ro=so.getBoundingClientRect();
       var cg=getComputedStyle(sg), co=getComputedStyle(so);
       // A computed border width is divided by the modal's zoom, so 1px reads
       // 0.769px at zoom 1.3: test the style and a positive width, not 1.
       if(cg.borderTopStyle!=='solid'||!(parseFloat(cg.borderTopWidth)>0)||co.borderTopStyle!=='solid'||!(parseFloat(co.borderTopWidth)>0)) bad.push('a section has no border of its own');
       if(cg.borderTopColor===co.borderTopColor) bad.push('both sections share one border colour, so nothing tells them apart');
       var gap=ro.top-rg.bottom;
       if(!(gap>=8)) bad.push('the two sections are '+Math.round(gap)+' px apart, which is not clear air');
       if(!/THE GAMBLE/.test(sg.textContent)||!/LIMITED TIME OFFER/.test(so.textContent)) bad.push('the section heads are not THE GAMBLE and LIMITED TIME OFFER');
       if(!sg.querySelector('#gamblebtn')) bad.push('the Gamble button is not inside THE GAMBLE');
       if(!so.querySelector('#wirtlot')) bad.push('the offer card is not inside LIMITED TIME OFFER');
     }
     // FOUR: the clock. Same key across one five-minute window, a different
     // draw is at least possible across it, and the countdown never exceeds it.
     var t0=Math.floor(1750000000000/300000)*300000, K0=wirtLotKey(t0)[0];
